return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Plugin Search руу очно уу','Activate %s' => '%s-г идэвхжүүлнэ үү','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s нь</strong> <strong>%2$s-г</strong> суулгаж, идэвхжүүлэхийг шаарддаг. <a href="%4$s">%3$s</a>','Enter your code here' => 'Кодоо энд оруулна уу','Add %s' => '%s нэмнэ үү','Remove' => 'Устгах','Order number and receipt will be sent to this email address.' => 'Захиалгын дугаар болон баримтыг энэ имэйл хаяг руу илгээнэ.','Apartment, unit, building, floor, etc.' => 'Орон сууц, нэгж, барилга, шал гэх мэт.','Shipping phone' => 'Хүргэлтийн утас','Only used for shipping-related questions.' => 'Зөвхөн тээвэрлэлттэй холбоотой асуултуудад ашигладаг.','Single step' => 'Нэг алхам','Click to go to the order summary' => 'Захиалгын хураангуй руу очихын тулд дарна уу','Cart total:' => 'Сагс нийт:','Proceed to %s' => '%s руу үргэлжлүүлнэ үү','Proceed to contact' => 'Холбоо барихыг үргэлжлүүлнэ үү','Proceed to shipping' => 'Тээвэрлэлтийг үргэлжлүүлнэ үү','Proceed to billing' => 'Төлбөр тооцоог үргэлжлүүлнэ үү','Proceed to payment' => 'Төлбөрийг үргэлжлүүлнэ үү','Shipping method' => 'Хүргэлтийн арга','Additional notes' => 'Нэмэлт тэмдэглэл','Payment method' => 'Төлбөрийн арга','Step %1$s of %2$s' => '%2$s-н %1$s алхам','Change: %s' => 'Өөрчлөлт: %s','Not selected yet.' => 'Одоогоор сонгоогүй байна.','Same as shipping address' => 'Хүргэлтийн хаягтай адилхан','Same as billing address' => 'Тооцооны хаягтай адилхан','Order summary' => 'Захиалгын хураангуй','Edit cart' => 'Сагс засах','Did you mean %s?' => 'Та %s гэсэн үг үү?','Change email address to: {suggestion-value}' => 'Имэйл хаягийг дараах болгож өөрчлөх: {suggestion-value}','This is a required field.' => 'Энэ бол шаардлагатай талбар юм.','This is not a valid email address.' => 'Энэ буруу имэйл хаяг байна.','This field does not match the related field value.' => 'Энэ талбар нь холбогдох талбарын утгатай тохирохгүй байна.','The CPF number "{cpf_number}" is invalid.' => '&quot;{cpf_number}&quot; CPF дугаар буруу байна.','The CNPJ number "{cnpj_number}" is invalid.' => 'CNPJ дугаар &quot;{cnpj_number}&quot; буруу байна.','(Required)' => '(Шаардлагатай)','Checkout Header - Desktop' => 'Тооцооны толгой хэсэг - Ширээний компьютер','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Тооцооны толгой хэсэгт виджетүүдийг том дэлгэц дээр харуулах. Зөвхөн залгаасын тооцооны толгой хэсгийг ашиглаж байгаа тохиолдолд л харагдана.','Checkout Header - Mobile' => 'Тооцооны толгой хэсэг - Гар утас','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Хөдөлгөөнт төхөөрөмжүүдийн тооцооны толгойн доор виджетүүдийг харуул. Зөвхөн залгаасын тооцооны толгой хэсгийг ашиглаж байгаа тохиолдолд л харагдана.','Checkout Sidebar' => 'Тооцооны хажуугийн самбар','Display widgets on the checkout sidebar after the order summary.' => 'Захиалгын хураангуйны дараа төлбөрийн талбар дээр виджетүүдийг харуулах.','Checkout Order Summary' => 'Тооцооны захиалгын хураангуй','Display widgets inside the order summary at the checkout page.' => 'Тооцоо хийх хуудасны захиалгын хураангуй дотор виджетүүдийг харуулах.','Checkout Below Place Order' => 'Захиалгын доор төлбөрөө хийнэ үү','Display widgets below the place order button at the checkout page.' => 'Тооцоо хийх хуудасны захиалга өгөх товчны доор виджетүүдийг харуул.','Checkout Footer' => 'Тооцооны хөл хэсэг','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Тооцооны хөл хэсэгт виджетүүдийг харуулах. Зөвхөн залгаасын төлбөрийн хөлийг ашиглаж байгаа тохиолдолд л харагдана.','Classic' => 'Сонгодог','Boxed' => 'Хайрцагласан','Split' => 'Хуваах','Minimalist' => 'Минималист','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'CodeRockz-ийн Fluid Checkout болон Delivery Date залгаасууд','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>Бид таныг CodeRockz-н WooCommerce (үнэгүй ба PRO)-д зориулсан Хүргэлтийн &amp; Хүргэлтийн огнооны цагийг ашиглаж байгааг илрүүллээ. Эдгээр залгаасуудтай нэгтгэх нь Fluid Checkout PRO руу шилжсэн.</p>','Upgrade to PRO' => 'PRO руу шинэчлэх','Fluid Checkout database updated successfully' => 'Fluid Checkout мэдээллийн санг амжилттай шинэчилсэн','The database changes where applied successfully.' => 'Өгөгдлийн сан амжилттай хэрэгжсэн газарт өөрчлөгдөнө.','Dismiss' => 'Өгүүлэх','Fluid Checkout database update' => 'Fluid Checkout мэдээллийн сангийн шинэчлэл','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Мэдээллийн санд зарим өөрчлөлт оруулах шаардлагатай. Аливаа шинэчлэлтийн нэгэн адил бид <strong>үргэлжлүүлэхээсээ өмнө вэбсайтаа бүрэн нөөцлөхийг</strong> зөвлөж байна.','Update database' => 'Өгөгдлийн санг шинэчлэх','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout нь Divi Builder тооцооны загварт тохирохгүй байна','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Fluid Checkout-д ажиллахын тулд сонгодог WooCommerce богино код дээр суурилсан төлбөрийн маягт хэрэгтэй. Тооцоо хийх хуудасны харагдах байдал, мэдрэмжийг өөрчлөхийн тулд Divi Builder-г ашиглах үед сонгодог богино кодуудыг төлбөрийн хуудасны хэсэг бүрт Divi Builder-ийн захиалгат виджетүүдээр сольдог. Эдгээр тусгай виджетүүд нь Fluid Checkout-д тохирохгүй байна.</p><p> Divi Builder виджетүүдийг <code>[woocommerce_checkout]</code> богино код агуулсан текстийн виджетээр сольж, тооцоо хийх хуудсаа засна уу.</p>','Edit the checkout page' => 'Тооцоо хийх хуудсыг засварлана уу','Read the documentation.' => 'Баримт бичгийг уншина уу.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Fluid Checkout-г ашиглах үед Германчлагдсан PRO олон шатлалт тооцооны функцийг идэвхгүй болгох шаардлагатай','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Fluid Checkout-г ашиглах үед Germanized PRO залгаасын олон шатлалт функц нь шаардлагагүй болж, <strong>шинэ захиалга боловсруулах явцад ноцтой алдаа</strong> гаргахад хүргэдэг. Залгаасны тохиргооноос Germanized PRO олон шаттай тооцоо хийх функцийг идэвхгүй болгоно уу.','Go to Germanized settings' => 'Германчлагдсан тохиргоо руу очно уу','Thanks for choosing Fluid Checkout!' => 'Fluid Checkout-г сонгосонд баярлалаа!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Та залгаасыг багагүй хугацаанд ашиглаж байна. Энэ нь танд хэр таалагдаж байна вэ?<br> Бидэнд хурдан үнэлгээ өгнө үү, бид санал хүсэлт болгонд талархаж байгаа бөгөөд энэ нь залгаасыг үргэлжлүүлэн сайжруулахад биднийг урамшуулж байна :)','Rate the plugin' => 'Plugin-д үнэлгээ өгнө үү','I need help!' => 'Надад тусламж хэрэгтэй байна!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Quadlayers-ийн WooCommerce Checkout Manager-ийн зарим онцлог нь үүнийг Fluid Checkout-тэй ашиглах үед санаснаар ажиллахгүй байж магадгүй юм. Дэлгэрэнгүй мэдээлэл болон өөр шийдлүүдийг авахын тулд <a href="%s">манай баримт бичгийг</a> уншина уу.','Read documentation' => 'Баримт бичгийг уншина уу','Don\'t show this again' => 'Үүнийг дахиж битгий харуул','Fluid Checkout PRO' => 'Fluid Checkout PRO','More design templates' => 'Илүү олон дизайны загварууд','Optimized cart page' => 'Оновчтой тэрэгний хуудас','Optimized order received / thank you page' => 'Хүлээн авсан захиалга / баярлалаа хуудас','Edit cart contents at checkout page' => 'Тооцоо хийх хуудсан дээр сагсны агуулгыг засна уу','Account matching / user matching' => 'Бүртгэл тааруулах / хэрэглэгчийн тааруулах','Trust symbols on the cart and thank you pages' => 'Сагс болон баярлалаа хуудсууд дээрх итгэмжлэлийн тэмдэг','More positions for the coupon code on the checkout page' => 'Тооцоо хийх хуудсан дээрх купоны кодын бусад байрлалууд','International phone numbers' => 'Олон улсын утасны дугаарууд','Gift messages and packing slips' => 'Бэлэг дурсгалын зурвас, баглаа боодлын хуудас','Local pickup and in-store collection' => 'Орон нутгийн хүлээн авалт болон дэлгүүрийн цуглуулга','EU-VAT Assistant' => 'ЕХ-НӨАТ-ын туслах','I already have it – Hide this offer' => 'Надад аль хэдийн байгаа - Энэ саналыг нуу','Activated' => 'Идэвхжүүлсэн','Address book' => 'Хаягийн дэвтэр','Select an image' => 'Зураг сонгоно уу','Cart layout' => 'Сагсны зохион байгуулалт','Cart optimizations' => 'Сагсыг оновчтой болгох','Enable cart page optimizations' => 'Сагсны хуудасны оновчлолыг идэвхжүүлэх','Header and footer template' => 'Толгой ба хөлийн загвар','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Хуудасны толгой болон хөлийг анхаарал сарниулахгүй ашиглах эсвэл одоо идэвхтэй байгаа сэдвийн толгой болон хөлийг хадгалах эсэхийг хянадаг.','Distraction free header and footer' => 'Анхаарал сарниулахгүй толгой ба хөл','Theme\'s header and footer' => 'Сэдвийн толгой ба хөл хэсэг','Cart elements' => 'Сагсны элементүүд','Make the order summary stay visible on the cart page while scrolling' => 'Гүйлгэх явцад захиалгын хураангуйг сагсанд харагдахуйц байлгах','Coupon codes' => 'Купоны кодууд','Hidden' => 'Нуугдсан','Before the cart items section' => 'Сагсны эд зүйлс хэсгийн өмнө','Inside the cart items section' => 'Сагсны эд зүйлсийн хэсэг дотор','After the cart items section' => 'Сагсны зүйлийн дараа','Before the shipping section' => 'Тээвэрлэлтийн хэсгийн өмнө','After the shipping section' => 'Тээвэрлэлтийн хэсгийн дараа','Before the order summary' => 'Захиалгын хураангуйгаас өмнө','Inside the order summary' => 'Захиалгын хураангуй дотор','Before the order totals' => 'Захиалгын нийт дүнгээс өмнө','After the order totals' => 'Захиалгын нийт дүнгийн дараа','After the order summary' => 'Захиалгын хураангуй дараа','Shipping' => 'Хүргэлт','Select position where to display the shipping costs and calculator on the cart page.' => 'Сагсны хуудсан дээр тээврийн зардал болон тооцоолуурыг харуулах байрлалыг сонгоно уу.','Display as a cart section' => 'Сагсны хэсэг болгон харуулах','Cross-sells' => 'Хөндлөн зарах','Select position where to display the cross-sells section on the cart page.' => 'Сагсны хуудсан дээрх хөндлөн борлуулалтын хэсгийг харуулах байршлыг сонгоно уу.','Before the cart actions' => 'Сагс хийхээс өмнө','After the cart actions' => 'Сагсны үйлдлүүдийн дараа','Layout of cross-sell items on the cart page.' => 'Сагсны хуудсан дээрх хөндлөн зарах зүйлсийн байршил.','Optimized horizontal cross-sells layout' => 'Хэвтээ хөндлөн борлуулалтыг оновчтой болгосон','Theme\'s cross-sells layout' => 'Загварын хөндлөн борлуулалтын загвар','Number of cross-sell items to display on the cart page' => 'Сагсны хуудсан дээр харуулах хөндлөн зарах зүйлсийн тоо','Add widget areas to the cart page' => 'Сагсны хуудсанд виджетийн хэсгүүдийг нэмнэ үү','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Эдгээр виджетийн хэсгүүдийг сагсан дээрх хуудсан дээр итгэлцлийн тэмдэг болон итгэлийн тэмдгийг нэмэхэд ашигладаг.','Checkout' => 'Тооцоо хийх','Checkout layout' => 'Тооцооны зураглал','Design template' => 'Дизайн загвар','Dark mode' => 'Харанхуй горим','Enable dark mode' => 'Харанхуй горимыг идэвхжүүл','Logo image' => 'Лого зураг','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'Тооцоо хийх хуудасны толгой хэсэгт харуулах зургийг сонгоно уу. Зөвхөн анхаарал сарниулахгүй толгой болон хөлийг ашиглах үед л хамаарна.','Header background color' => 'Толгой хэсгийн дэвсгэр өнгө','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Тооцоо хийх хуудасны толгой хэсэгт арын өнгийг сонгоно уу. Зөвхөн анхаарал сарниулахгүй толгой ба хөлийг ашиглах үед л хамаарна.','HTML color value. ie: #f3f3f3' => 'HTML өнгөний утга. өөрөөр хэлбэл: #f3f3f3','Page background color' => 'Хуудасны дэвсгэр өнгө','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Тооцоо хийх хуудасны дэвсгэр өнгийг сонгоно уу. <em>Биеийн</em> элементэд өнгө хэрэглэнэ.','Footer background color' => 'Хөлийн дэвсгэр өнгө','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Тооцоо хийх хуудасны хөлийн дэвсгэрийн өнгийг сонгоно уу. Зөвхөн анхаарал сарниулахгүй толгой болон хөлийг ашиглах үед л хамаарна.','Progress bar' => 'Явцын талбар','Make the checkout progress bar stay visible while scrolling' => 'Тооцоо хийх явцын мөрийг гүйлгэж байх үед харагдуулна','Express checkout' => 'Шуурхай тооцоо хийх','Enable the express checkout section' => 'Экспресс тооцооны хэсгийг идэвхжүүлнэ үү','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Дэмжигдсэн төлбөрийн гарцууд энэ функцийг идэвхжүүлсэн үед төлбөр тооцоо хийх үед түргэн тооцоо хийх хэсгийг харуулна.','Display express checkout buttons in one line for larger screens' => 'Том дэлгэцийн хувьд хурдан тооцоо хийх товчлууруудыг нэг мөрөнд харуул','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'Тохиромжтой буухиа тооцооны төлбөрийн гарцаар төлбөр хийхдээ нэмэлт төлбөр хийх шаардлагатай талбаруудыг үл тоомсорло','Make the order summary stay visible while scrolling' => 'Гүйлгэх явцад захиалгын хураангуйг харагдахуйц байлгах','Choose a background color for the order summary section.' => 'Захиалгын хураангуй хэсэгт дэвсгэр өнгө сонгоно уу.','Highlight the order totals row in the order summary table' => 'Захиалгын хураангуй хүснэгтийн захиалгын нийт мөрийг тодруулна уу','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Захиалгын хураангуй хэсэг нь тодруулсан дэвсгэр өнгөгүй үед хамгийн ашигтай байдаг. Fluid Checkout PRO-г ашиглах үед &quot;Сагс&quot;, &quot;Хүлээн авсан захиалга&quot; болон &quot;Захиалга харах&quot; хуудсуудад мөн хамааралтай байж болно.','Action link on the order summary at checkout.' => 'Тооцоо хийх үед захиалгын хураангуй дээрх үйлдлийн холбоос.','Edit cart link' => 'Сагсны холбоосыг засах','Cart items count' => 'Сагсны барааг тоолно','Link to shop page' => 'Дэлгүүр хуудас руу холбоно уу','Cart items' => 'Сагсны эд зүйлс','Hide cart items errors at the checkout page' => 'Тооцоо хийх хуудсан дээр сагсанд байгаа бараануудын алдааг нуу','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'Төлбөрийн хуудасны дээд талд сагсанд байгаа зүйлийн алдааны мессежийг бүү харуул. Худалдан авалтыг дуусгахын тулд төлбөрийн маягтыг илгээх үед эдгээр алдааны мэдэгдлүүд үргэлж харагдах болно.','Place order' => 'Захиалга өгөх','Define the position to display "Place order" and terms checkbox section.' => '&quot;Захиалга өгөх&quot; болон нөхцөлийг шалгах хайрцагны хэсгийг харуулах байрлалыг тодорхойлно уу.','Some options might not be compatible with some plugins and themes.' => 'Зарим сонголтууд нь зарим залгаасууд болон загваруудтай нийцэхгүй байж магадгүй.','Below the payment section' => 'Төлбөрийн хэсгийн доор','Below the order summary' => 'Захиалгын хураангуй доор','Both below the payment section and the order summary' => 'Төлбөрийн хэсэг болон захиалгын хураангуй доор хоёулаа','Add widget areas to the checkout page' => 'Тооцоо хийх хуудсанд виджетийн хэсгүүдийг нэмнэ үү','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Эдгээр виджетийн хэсгүүдийг тооцооны хуудсан дээр итгэлцлийн тэмдэг болон итгэлийн тэмдгийг нэмэхэд ашигладаг.','Display the coupon codes section title' => 'Купон кодын хэсгийн гарчгийг харуулах','Select position where to display the coupon codes section on the checkout page.' => 'Тооцоо хийх хуудсан дээрх купоны кодыг харуулах байрлалыг сонгоно уу.','Before the checkout steps' => 'Тооцоо хийх алхамуудын өмнө','As a substep before payment methods' => 'Төлбөрийн аргуудаас өмнөх дэд алхам болгон','As a substep after payment methods' => 'Төлбөрийн аргын дараах дэд алхам болгон','Default button style' => 'Өгөгдмөл товчлуурын загвар','"Add" link button' => '&quot;Нэмэх&quot; холбоос товч','Checkout fields' => 'Тооцоо хийх талбарууд','Optional fields' => 'Нэмэлт талбарууд','Hide optional fields behind a link button' => 'Холбоос товчлуурын ард нэмэлт талбаруудыг нуу','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'Нээлттэй оруулах талбаруудын тоог багасгахын тулд энэ сонголтыг шалгахыг зөвлөж байна, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">судалгааг уншина уу</a> .','Do not hide "Address line 2" fields behind a link button' => 'Холбоос товчлуурын ард &quot;Хаяг мөр 2&quot; талбарыг бүү нуу','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Ихэнх үйлчлүүлэгчдэд &quot;Хаяг мөр 2&quot; талбар үнэхээр шаардлагатай үед эсвэл зөв тээвэрлэлтийн хаягийг авах нь чухал үед (жишээ нь хоол хүнс болон бусад түргэн мууддаг бүтээгдэхүүнийг хүргэж байгаа бол) зөвлөж байна.','Billing address' => 'Тооцооны хаяг','Select position where to display the billing address section on the checkout page.' => 'Тооцоо хийх хуудасны төлбөрийн хаягийн хэсгийг харуулах байрлалыг сонгоно уу.','As a step before shipping' => 'Тээвэрлэлтийн өмнөх алхам болгон','As a sub-step before the shipping address section' => 'Тээвэрлэлтийн хаягийн хэсгийн өмнөх дэд алхам болгон','As a sub-step after the shipping address section' => 'Тээвэрлэлтийн хаяг хэсгийн дараа дэд алхам болгон','As a step after shipping' => 'Тээвэрлэлтийн дараах алхам болгон','As a sub-step before the payment section' => 'Төлбөрийн хэсгийн өмнөх дэд алхам болгон','Force billing and shipping addresses to the same (single section)' => 'Төлбөрийн болон хүргэлтийн хаягийг ижил (нэг хэсэг) рүү хүчээр оруулах','Checkbox for "Same as shipping/billing address" checked by default' => '&quot;Тээвэрлэлтийн/төлбөрийн хаягтай ижил&quot; гэсэн нүдийг өгөгдмөлөөр тэмдэглэсэн байна','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => '&quot;Тээвэрлэлтийн хаягтай ижил&quot; гэсэн нүдийг анхдагчаар тэмдэглэснээр ачааны хаягийн хэсгийг эхлээд харуулах үед эхэлнэ.<br> &quot;Төлбөрийн хаягтай ижил&quot; гэсэн нүд нь &quot;Төлбөрийн хаяг&quot; хэсгийг эхлээд харуулах үед анхдагчаар тэмдэглэгдсэн байдлаар эхэлнэ.<br> Тооцоо хийх үед нээлттэй оролтын талбаруудын тоог эрс багасгахын тулд энэ сонголтыг тэмдэглэж үлдээхийг зөвлөж байна, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">судалгааг уншина уу</a> .','Highlight the billing address section in the checkout form' => 'Тооцоо хийх маягтын төлбөрийн хаягийн хэсгийг тодруулна уу','Shipping address' => 'Хүргэлтийн хаяг','Highlight the shipping address section in the checkout form' => 'Төлбөрийн маягтаас тээвэрлэлтийн хаягийн хэсгийг тодруулна уу','Shipping methods' => 'Хүргэлтийн аргууд','Choose in which position to display the shipping methods section.' => 'Тээвэрлэлтийн аргууд хэсгийг аль байрлалд харуулахаа сонгоно уу.','Before shipping address' => 'Хүргэлтийн өмнө хаяг','After shipping address' => 'Хүргэлтийн хаягийн дараа','Local pickup' => 'Орон нутгийн хүлээн авах','Removes shipping address section when a local pickup shipping method is selected.' => 'Орон нутгийн хүлээн авах тээвэрлэлтийн аргыг сонгох үед тээвэрлэлтийн хаягийн хэсгийг арилгана.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'Орон нутгийн хүлээн авах тээвэрлэлтийн аргыг сонгох үед тээвэрлэлтийн хаягийг хүлээн авах цэгийн байршлаар солино.','Choose which address to save as the shipping address for local pickup orders.' => 'Орон нутгаас очиж авах захиалгын тээвэрлэлтийн хаяг болгон хадгалах хаягийг сонгоно уу.','Save the selected pickup location' => 'Сонгосон хүлээн авах байршлыг хадгална уу','Save same as the billing address' => 'Төлбөрийн хаягтай адил хадгална','Do not save any shipping address' => 'Тээвэрлэлтийн хаягийг бүү хадгал','Company name field for shipping address' => 'Хүргэлтийн хаягийн компанийн нэрийн талбар','Change visibility for the company name field for the shipping address section on the checkout form.' => 'Төлбөрийн маягт дээрх тээвэрлэлтийн хаяг хэсгийн компанийн нэрийн талбарын харагдах байдлыг өөрчлөх.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Хэрэв талбарыг харагдах байдлын өгөгдмөл төлөв &quot;заавал биш&quot; гэж тохируулсан бол бусад залгаасуудад шаардлагатай өөрчлөлтүүдийг оруулахын тулд ямар ч өөрчлөлт хийхгүй.','Hidden (remove field)' => 'Нуугдсан (талбарыг устгах)','Optional' => 'Нэмэлт','Required' => 'Шаардлагатай','Add shipping phone field to the checkout form.' => 'Төлбөрийн маягтанд хүргэлтийн утасны талбар нэмнэ үү.','Choose in which step to display the shipping phone field.' => 'Тээвэрлэлтийн утасны талбарыг аль алхамд харуулахаа сонгоно уу.','Contact step' => 'Холбоо барих алхам','Billing phone' => 'Тооцооны утас','Add billing phone field to the checkout form.' => 'Тооцооны маягтанд төлбөрийн утасны талбарыг нэмнэ үү.','Choose in which step to display the billing phone field.' => 'Тооцооны утасны талбарыг аль алхамд харуулахаа сонгоно уу.','Show country code beside the flag' => 'Тугны хажууд улсын кодыг харуул','Show an example of a valid phone number inside phone fields' => 'Утасны талбарт хүчинтэй утасны дугаарын жишээг үзүүл','Do not change placeholders' => 'Орлуулагчийг бүү соль','Show if not defined' => 'Тодорхойлогдоогүй бол харуулах','Always show' => 'Үргэлж харуулах','Order notes' => 'Захиалгын тэмдэглэл','Define the visibility of the additional order notes field.' => 'Нэмэлт захиалгын тэмдэглэлийн талбарын харагдах байдлыг тодорхойлно уу.','Gift options' => 'Бэлэг дурсгалын сонголтууд','Allow customers to add a gift message and other gift related options to the order.' => 'Захиалгад бэлгийн мессеж болон бусад бэлэгтэй холбоотой сонголтуудыг нэмэхийг харилцагчдад зөвшөөрнө үү.','Display the gift message as part of the order details table instead of a separate section' => 'Бэлэглэлийн мессежийг тусдаа хэсгийн оронд захиалгын дэлгэрэнгүй хүснэгтийн нэг хэсэг болгон харуул','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'Энэ сонголт нь захиалгын баталгаажуулалтын хуудас (баярлалаа хуудас) болон дансны хуудас, имэйл, баглаа боодлын хуудасны захиалгын дэлгэрэнгүй мэдээлэлд нөлөөлнө.','Account matching' => 'Бүртгэл тааруулах','Enable the account matching feature' => 'Бүртгэлийг тохируулах функцийг идэвхжүүлнэ үү','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'Үйлчлүүлэгчийн холбоо барих хаягтай данс аль хэдийн байгаа бол зочин хэрэглэгчийн захиалгыг одоо байгаа данстай нь холбоно уу.','Display message when an account exists with the email address provided' => 'Өгөгдсөн имэйл хаягтай бүртгэл байгаа үед мессежийг харуулах','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'Бүртгэл үүсгэх талбаруудыг мэдэгдэл болон нэвтрэх сонголтоор солино. Зарим нөхцөл байдалд үйлчлүүлэгчдийн нууцлалыг хамгаалахын тулд энэ сонголтыг идэвхгүй болгохыг зөвлөж байна.','Dashboard' => 'Хяналтын самбар','Integrations' => 'Интеграци','License keys' => 'Лицензийн түлхүүрүүд','Visit our website for more information about our plugins and add-ons.' => 'Манай вэб сайтад зочилж манай залгаас болон нэмэлтүүдийн талаар дэлгэрэнгүй мэдээлэл аваарай.','Order pay page' => 'Захиалгын төлбөрийн хуудас','Order pay' => 'Захиалгын төлбөр','Enable order pay page optimizations' => 'Захиалгын төлбөрийн хуудасны оновчлолыг идэвхжүүлэх','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Үйлчлүүлэгчээс төлбөр хүлээгдэж буй одоо байгаа захиалгын төлбөрийн хуудасны бүдүүвчийг өөрчилдөг.','Add widget areas to the order pay page' => 'Захиалгын төлбөрийн хуудсанд виджетийн хэсгүүдийг нэмнэ үү','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Эдгээр виджетийн хэсгүүдийг захиалгын төлбөрийн хуудсан дээр итгэлцлийн тэмдэг болон итгэлийн тэмдгийг нэмэхэд ашигладаг.','Thank you page & order details layout' => 'Баярлалаа хуудас болон захиалгын дэлгэрэнгүй зураглал','Order details optimizations' => 'Захиалгын дэлгэрэнгүй оновчлол','Enable thank you page and order details optimizations' => 'Баярлалаа хуудас болон захиалгын дэлгэрэнгүй оновчлолыг идэвхжүүлнэ үү','Changes the layout of order details on the thank you page and account pages.' => 'Баярлалаа хуудас болон дансны хуудасны захиалгын дэлгэрэнгүй мэдээллийг өөрчилнө.','Enable order details customizations on email notifications' => 'Имэйл мэдэгдэл дээр захиалгын дэлгэрэнгүй тохиргоог идэвхжүүлнэ үү','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Имэйл мэдэгдэл дээр шинэ хэсгүүдийг харуулах, хэсгүүдийн дарааллыг өөрчлөх. Имэйл мэдэгдлийн захиалгын дэлгэрэнгүй хэв маяг өөрчлөгдөөгүй хэвээр байна.','Thank you page' => 'Баярлалаа хуудас','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Эдгээр сонголтууд нь хүлээн авсан захиалга эсвэл захиалгын баталгаажуулалтын хуудас гэгддэг баярлалаа хуудаст нөлөөлдөг.','Order details layout' => 'Захиалгын дэлгэрэнгүй зураглал','Display the order details with wide layout on the thank you page' => 'Баярлалаа гэсэн хуудас дээр захиалгын дэлгэрэнгүй мэдээллийг өргөн байрлуулна уу','Add widget areas to the thank you page' => 'Баярлалаа хуудсанд виджетийн хэсгүүдийг нэмнэ үү','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Эдгээр виджетийн хэсгүүдийг баярлалаа хуудсанд итгэлцлийн тэмдэг болон итгэлийн тэмдгийг нэмэхэд ашигладаг.','Order actions' => 'Үйлдлийг захиалах','Choose in which position to display the order actions.' => 'Захиалгын үйлдлийг аль байрлалд харуулахаа сонгоно уу.','Inside the order overview' => 'Захиалгын тойм дотор','After the order overview' => 'Захиалгын тойм дараа','After order sections' => 'Захиалгын хэсгүүдийн дараа','Order status' => 'Захиалгын статус','Display the order status progress bar' => 'Захиалгын төлөв байдлын мөрийг харуулах','Choose in which position to display the section.' => 'Хэсгийг аль байрлалд харуулахаа сонгоно уу.','After the order overview and payment instructions' => 'Захиалгын тойм болон төлбөрийн зааврын дараа','Before the order items section' => 'Захиалгын зүйлсийн хэсгийн өмнө','Inside the order items section' => 'Захиалгын зүйлсийн хэсэг дотор','After the order items section' => 'Захиалгын зүйлс хэсгийн дараа','On the sidebar' => 'Хажуугийн самбар дээр','Order downloads' => 'Татаж авах захиалга','Gift message' => 'Бэлгийн мессеж','Tools' => 'Багаж хэрэгсэл','Troubleshooting' => 'Алдааг олж засварлах','Debug options' => 'Дибаг хийх сонголтууд','Debug mode' => 'Дибаг хийх горим','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'Дибаг хийх горимыг ашиглах нь вэбсайтын гүйцэтгэлд нөлөөлдөг. Энэ сонголтыг зөвхөн алдааг олж засварлах үед ашиглана уу.','Load unminified assets' => 'Хэмжээгүй хөрөнгийг ачаалах','Enhanced select fields' => 'Сайжруулсан сонголтын талбарууд','Fix automatic zoom-in on form fields' => 'Маягтын талбаруудыг автоматаар томруулж байгааг засаарай','Set <code>font-size</code> inside form fields to 16px' => 'Маягтын талбар доторх <code>font-size</code> 16px болгож тохируулна уу','Fluid Checkout' => 'Шингэнийг шалгах','Settings' => 'Тохиргоо','Support' => 'Дэмжлэг','(PRO)' => '(PRO)','(experimental)' => '(туршилтын)','Please verify your phone number.' => 'Утасны дугаараа баталгаажуулна уу.','The Bluehost Plugin' => 'Bluehost Plugin','Custom fields' => 'Тусгай талбарууд','Enable custom shipping email field' => 'Захиалгат хүргэх имэйл талбарыг идэвхжүүлнэ үү','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Идэвхжүүлсэн үед Bluehost залгаасаас илгээсэн имэйлийн талбар нь төлбөрийн маягтанд нэмэгдэх болно.','Captcha Pro by BestWebSoft' => 'BestWebSoft-ийн Captcha Pro','Captcha position' => 'Captcha байрлал','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Captcha хэсгийг харуулах байрлалыг тодорхойлно уу. Сонгосон captcha төрлөөс хамааран зарим байрлал ажиллахгүй байж магадгүй.','Selecting a pickup point is required before proceeding.' => 'Үргэлжлүүлэхийн өмнө хүлээн авах цэгийг сонгох шаардлагатай.','Pickup point' => 'Хүлээн авах цэг','Pickup point not selected yet.' => 'Хүлээн авах цэг хараахан сонгогдоогүй байна.','Pickup point:' => 'Хүлээн авах цэг:','Mailchimp for WooCommerce' => 'WooCommerce-д зориулсан Mailchimp','Subscribe checkbox' => 'Бүртгүүлэх нүдийг сонгоно уу','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'Тооцоо хийх хуудсан дээрх бүртгүүлэх хайрцгийг дарж, холбоо барих алхам дээр үргэлж харуул','Before Shipping Address' => 'Хүргэлтийн өмнө хаяг','(originally "%s")' => '(анх &quot;%s&quot;)','After Shipping Address' => 'Хүргэлтийн дараах хаяг','Selecting a collection point is required when shipping with FermoPoint.' => 'FermoPoint-ээр тээвэрлэх үед цуглуулах цэгийг сонгох шаардлагатай.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Хэрэв тэмдэглэсэн бол үсгийн алдааг хэрэглэгчдэд имэйлээр мэдэгдэнэ. (Fluid Checkout функцийг санал болгож байгаа тул энэ функцийг идэвхгүй болгосон. Энэ сонголтод хийсэн өөрчлөлт хүчин төгөлдөр болохгүй)','Enable Mail Check: (disabled feature)' => 'Мэйл шалгахыг идэвхжүүлэх: (идэвхгүй болгосон функц)','Carrier:' => 'Оператор:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - WooCommerce имэйл маркетинг','Sign up checkbox position' => 'Бүртгүүлэх хайрцагны байрлал','Move the sign up checkbox to the contact step' => 'Бүртгүүлэх нүдийг холбоо барих алхам руу шилжүүлнэ үү','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Идэвхжүүлсэн үед тэмдэглэгээг Sendinblue залгаасын тохиргоонд тодорхойлсон дэлгэцийн байршлаас үл хамааран холбоо барих алхам руу шилжүүлнэ.','Theme Betheme' => 'Бетемийн сэдэв','Checkout progress' => 'Тооцооны явц','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'Тооцоо хийх, тэрэг болон захиалгын хүлээн авсан хуудсан дээр Бетемээс тооцоо хийх алхамуудын хэсгийг гарга.','Theme Fennik' => 'Фенникийн сэдэв','Breadcrumbs' => 'Талхны үйрмэг','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Fluid Checkout-ийн толгой ба хөлийг ашиглах үед Fennik-ийн сэдвээс Breadcrumbs хэсгийг гарга.','Theme Go' => 'Theme Go','My account layout' => 'Миний дансны зураглал','Enable wide layout on "My account" page.' => '&quot;Миний данс&quot; хуудасны өргөн байршлыг идэвхжүүлнэ үү.','Theme Impreza' => 'Impreza сэдэв','Header' => 'Толгой хэсэг','Spacing for site header at the checkout page (in pixels)' => 'Тооцоо хийх хуудсан дээрх сайтын толгой хэсгийн зай (пикселээр)','Only applicable when using the Impreza theme header at the checkout page.' => 'Тооцоо хийх хуудсан дээрх Impreza загварын толгой хэсгийг ашиглах үед л хамаарна.','Theme Kapee' => 'Сэдэв Капи','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'Тооцоо хийх, тэрэг болон захиалгын хүлээн авсан хуудсан дээрх Kapee-ийн загвараас төлбөрийн алхамуудын хэсгийг гарга.','Theme Porto' => 'Портогийн сэдэв','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'Тооцоо хийх, тэрэг болон захиалгын хүлээн авсан хуудсууд дээрх Порто сэдвээс төлбөрийн алхамуудын хэсгийг гарга.','Theme Pressmart' => 'Theme Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'Тооцоо хийх, тэрэг болон захиалгын хүлээн авсан хуудсан дээрх Pressmart-ын загвараас төлбөрийн алхамуудын хэсгийг гарга.','Theme The Gem' => '&quot;Эрдэнийн чулуу&quot; сэдэв','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Fluid Checkout толгой болон хөлийг ашиглах үед The Gem загвараас тооцоо хийх алхамуудын хэсгийг гарга.','Theme Woodmart' => 'Вудмарт сэдэв','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Fluid Checkout толгой болон хөлийг ашиглах үед Woodmart-ын загвараас төлбөрийн алхамуудын хэсгийг гарга.','Checkout options' => 'Тооцоо хийх сонголтууд','Disable the theme checkout options' => 'Загварын тооцоо хийх сонголтыг идэвхгүй болго','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'Сонголтууд нь бүтээгдэхүүний зураг, тоо хэмжээний талбар, устгах товчлуур болон тухайн сэдвийн дагуу нэмсэн бүтээгдэхүүний хуудасны холбоосыг анхдагчаар идэвхгүй болгосон байна.','Theme Atomion' => 'Atomion сэдэв','Order progress' => 'Захиалгын явц','Display order progress from the theme' => 'Загварын захиалгын явцыг харуулах','Display the form field labels visible on the page' => 'Хуудас дээр харагдах маягтын талбарын шошгыг харуул','It is recommended to keep this option enabled for a better user experience.' => 'Хэрэглэгчийн туршлагыг сайжруулахын тулд энэ сонголтыг идэвхтэй байлгахыг зөвлөж байна.','Theme ZK Nito' => 'ZK Nito сэдэв','Add extra fields to the checkout form' => 'Тооцооны маягтанд нэмэлт талбар нэмнэ үү','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'Тээвэрлэлтийн хаягийн хэсэгт нэмэлт и-мэйл болон тээврийн утасны талбар нэмнэ.','Go to the home page' => 'Нүүр хуудас руу очно уу','Skip to content' => 'Агуулга руу алгасах','Create an account' => 'Бүртгэл үүсгэх','Log in to your account' => 'Бүртгэлдээ нэвтэрнэ үү','Already have an account?' => 'Бүртгэлтэй юу?','Logged in as %1$s. <a href="%2$s">Log out</a>' => '%1$s нэрээр нэвтэрсэн. <a href="%2$s">Гарах</a>','Your order has a total amount due of %s. No further payment is needed.' => 'Таны захиалгын нийт дүн %s байна. Цаашид төлбөр хийх шаардлагагүй.','Close and continue with checkout' => 'Хаах ба тооцоогоо үргэлжлүүлнэ үү','Continue' => 'Үргэлжлүүлэх','Parcel terminal' => 'Илгээмжийн терминал','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>Энэ виджетийг Fluid Checkout-ээр сольсон.</p><p> Fluid Checkout-г ашиглах үед төлбөрийн хуудас зөв ажиллахын тулд анхны WooCommerce богино кодыг <code>[woocommerce_checkout]</code> ашиглах шаардлагатай.</p><p> Дэлгэрэнгүй мэдээллийг Fluid Checkout баримтаас авна уу.</p>','Theme The7' => 'Сэдэв 7','Additional header sections' => 'Нэмэлт толгойн хэсгүүд','Output additional header sections if enabled in the theme settings.' => 'Загварын тохиргоонд идэвхжүүлсэн бол нэмэлт толгой хэсгийг гаргана уу.','More information' => 'Дэлгэрэнгүй мэдээлэл','Pick a Locker' => 'Шүүгээ сонгох','Page template' => 'Хуудасны загвар','Use `Order confirmation` page template for block-based themes' => '&quot;Захиалга баталгаажуулах&quot; хуудасны загварыг блок дээр суурилсан загварт ашиглана уу','Only applies when using a block-based theme.' => 'Зөвхөн блокт суурилсан загвар ашиглах үед л хамаарна.','WooCommerce Stripe Gateway' => 'WooCommerce Stripe Gateway','Payment form' => 'Төлбөрийн маягт','Apply styles to the Stripe payment form fields' => 'Stripe төлбөрийн маягтын талбарт хэв маягийг оруулна уу','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Идэвхжүүлсэн үед Fluid Checkout нь залгаастай нийцтэй байхаар оновчтой загваруудыг ашиглах болно. Хэрэв та Stripe төлбөрийн маягтын талбарт тусгай загвар ашиглаж байгаа бол үүнийг идэвхгүй болгож болно.','Theme Nyture' => 'Nyture сэдэв','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Fluid Checkout-г ашиглах үед Nyture-ийн загвараас төлбөрийн алхамуудыг гарга.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'Дэлгүүрийн админ гараар үүсгэсэн эсвэл тооцоо хийх явцад дуусаагүй захиалгын төлбөрийг харилцагчдад хийх боломжийг олгоно.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Quadlayers-ийн WooCommerce Checkout Manager залгаас нь Fluid Checkout-тэй тохирохгүй байна','Company name field for billing address' => 'Тооцооны хаягийн компанийн нэрийн талбар','Change visibility for the company name field for the billing address section on the checkout form.' => 'Тооцооны маягт дээрх төлбөрийн хаягийн хэсгийн компанийн нэрийн талбарын харагдах байдлыг өөрчлөх.','Theme Bookshelf' => 'Сэдвийн номын тавиур','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'Fluid Checkout-г ашиглахдаа Bookshelf-ийн сэдвээс төлбөр тооцоо хийх алхамуудыг гарга.','Account password' => 'Дансны нууц үг','An account will be created with the information provided at checkout when completing the order.' => 'Захиалгыг бөглөхдөө тооцоо хийх үед өгсөн мэдээллээр данс үүсгэнэ.','Choose the style of the progress bar.' => 'Явцын талбарын хэв маягийг сонгоно уу.','Bars' => 'Баар','Theme Ireca' => 'Ireca сэдэв','WooCommerce page layout' => 'WooCommerce хуудасны зохион байгуулалт','Force wide layout on WooCommerce pages' => 'WooCommerce хуудсууд дээр өргөн байршлыг албадах','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'Энэ нь WooCommerce хуудасны төлбөр, тэрэг, хүлээн авсан захиалга, захиалгын төлбөр, дансны хуудсуудыг багтаасан агуулгын хэсгийг хэт нарийсгахгүй байхыг баталгаажуулдаг.','WooCommerce Smart Coupons' => 'WooCommerce ухаалаг купонууд','Position on checkout page' => 'Тооцоо хийх хуудсан дээрх байрлал','Choose where to display the available coupons section on the checkout page.' => 'Тооцоо хийх хуудасны боломжтой купоны хэсгийг хаана харуулахаа сонгоно уу.','Before the progress bar' => 'Явцын мөрний өмнө','After the progress bar' => 'Явцын мөрний дараа','Before coupon codes section' => 'Купон кодын өмнө','Format phone numbers according to the rules for each country.' => 'Улс бүрийн дүрмийн дагуу утасны дугаараа форматлаарай.','Use precise phone number validation' => 'Нарийвчилсан утасны дугаар баталгаажуулалтыг ашиглана уу','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'Энэ бол туршилтын онцлог бөгөөд бүх тохиргоонд санаснаар ажиллахгүй байж магадгүй. Үүнийг болгоомжтой хэрэглээрэй.','Phone number validation types used when precise validation is enabled.' => 'Нарийвчилсан баталгаажуулалтыг идэвхжүүлсэн үед ашигладаг утасны дугаар баталгаажуулалтын төрлүүд.','Mobile' => 'Гар утас','Fixed line' => 'Тогтмол шугам','Toll free' => 'Үнэгүй','Or' => 'Эсвэл','Contact' => 'Холбоо барих','Multi step' => 'Олон алхамтай','2 columns' => '2 багана','1 column' => '1 багана','Before checkout steps' => 'Төлбөр тооцоо хийхээс өмнөх алхамууд','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => '<em>&quot;1 багана&quot;</em> төлбөр тооцооны загварыг ашиглах үед энэ сонголтыг үргэлж <em>&quot;Төлбөр тооцооны өмнөх алхамууд&quot;</em> гэж тохируулсан байх бөгөөд мөн ширээний харагдацад хамаарна.','Position for the extra order summary section on mobile.' => 'Гар утсан дээрх нэмэлт захиалгын хураангуй хэсгийн байрлал.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => '<em>&quot;Сайтын толгой хэсэг дээр&quot;</em> гэсэн сонголт нь зөвхөн анхаарал сарниулах зүйлгүй толгой хэсгийг ашиглах үед л хүчинтэй.','On the site header (requires distraction-free header)' => 'Сайтын толгой хэсэг дээр (анхаарал сарниулах зүйлгүй толгой хэсэг шаардлагатай)','Initial state for the expansible order summary section on mobile.' => 'Гар утсан дээрх өргөтгөх боломжтой захиалгын хураангуй хэсгийн анхны төлөв.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => '<strong>Герман</strong> , <strong>Австри</strong> , <strong>Швейцарь</strong> , <strong>Нидерланд</strong> , <strong>Польш</strong> , <strong>Бельги</strong> , <strong>Франц</strong> зэрэг орнуудын зохицуулалтын шаардлагын дагуу үүнийг <em>өргөтгөсөн</em> гэж тохируулахыг бид зөвлөж байна.','Collapsed' => 'Хураагдсан','Expanded' => 'Өргөтгөсөн','Do not show' => 'Харуулахгүй','yes' => 'тийм','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Хэрэв төлбөр тооцооны хаягийн хэсгийг тээвэрлэлтийн хаягийн хэсгийн дараа харуулсан бөгөөд төлбөр тооцооны утасны талбарыг &quot;шаардлагатай&quot; гэж тохируулсан бол тээвэрлэлтийн утасны талбарыг &quot;шаардлагатай&quot; гэж оруулж болно. Энэ нь тухайн сонголтыг чагталсан үед тээвэрлэлтийн хаягийг төлбөр тооцооны хаяг руу хуулж болох эсэхийг баталгаажуулахын тулд шаардлагатай бөгөөд эс тэгвээс үйлчлүүлэгч төлбөр тооцооны маягтыг бөглөж чадахгүй байж магадгүй.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Хэрэв төлбөрийн хаягийн хэсэг нь тээвэрлэлтийн хаягийн хэсгийн өмнө гарч ирсэн бөгөөд тээвэрлэлтийн утасны талбарыг &quot;шаардлагатай&quot; гэж тохируулсан бол төлбөрийн утасны талбарыг &quot;шаардлагатай&quot; гэж оруулж болно. Энэ нь тухайн сонголтыг чагталсан үед тээвэрлэлтийн хаягийг төлбөрийн хаяг руу хуулж болох эсэхийг баталгаажуулахын тулд шаардлагатай бөгөөд эс тэгвээс үйлчлүүлэгч төлбөрийн маягтыг бөглөж чадахгүй байж магадгүй.','Settings profiles' => 'Тохиргооны профайлууд','Settings profile' => 'Тохиргооны профайл','You do not have permission to perform this action.' => 'Танд энэ үйлдлийг гүйцэтгэх зөвшөөрөл байхгүй байна.','You do not have permission to activate plugins.' => 'Та нэмэлт өргөтгөлүүдийг идэвхжүүлэх зөвшөөрөлгүй байна.','Missing plugin.' => 'Залгаас дутуу байна.','Plugin activated.' => 'Нэмэлт өргөтгөлийг идэвхжүүлсэн.','The following changes will be applied:' => 'Дараах өөрчлөлтүүд хэрэгжинэ:','Delete leftover options' => 'Үлдсэн сонголтуудыг устгах','This preview has expired. Reload the admin page to start a new preview.' => 'Энэ урьдчилсан үзлэгийн хугацаа дууссан. Шинэ урьдчилсан үзлэг эхлүүлэхийн тулд админ хуудсыг дахин ачаална уу.','Preview expired' => 'Урьдчилж харах хугацаа дууссан','Orders cannot be placed in the preview.' => 'Урьдчилан харах хэсэгт захиалга өгөх боломжгүй.','Logging in is not available in the preview.' => 'Урьдчилан харах хэсэгт нэвтрэх боломжгүй байна.','Accounts cannot be created in the preview.' => 'Урьдчилан харах хэсэгт бүртгэл үүсгэх боломжгүй.','Requests to other sites are blocked in the preview.' => 'Урьдчилан харах хэсэгт бусад сайтууд руу илгээх хүсэлтийг хаасан байна.','Processing…' => 'Боловсруулж байна…','Something went wrong. Please try again.' => 'Алдаа гарлаа. Дахин оролдоно уу.','Activate plugin' => 'Залгаасыг идэвхжүүлэх','Fluid Checkout PRO - The complete checkout package' => 'Шингэн худалдан авалтын PRO - Бүрэн төлбөрийн багц','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'Бүх PRO функцууд + бүх нэмэлтүүд, нэг үнээр. Дизайн загварууд, оновчтой сагс болон хүлээн авсан захиалгын хуудсууд, дансны тохируулга болон бусад олон зүйлс.','Optimized order pay page' => 'Оновчтой захиалгын төлбөрийн хуудас','Delayed account creation' => 'Бүртгэл үүсгэх хугацаа хойшлогдсон','Address autocomplete with Google Maps APIs' => 'Google газрын зургийн API-уудаар хаягийг автоматаар бөглөх','Multiple saved addresses with the address book' => 'Хаягийн дэвтэрт хадгалагдсан олон хаяг','EU-VAT assistant' => 'Европын Холбооны НӨАТ-ын туслах','Hide this section' => 'Энэ хэсгийг нуух','Learn more' => 'Дэлгэрэнгүй мэдээлэл авах','Get early access' => 'Эрт хандах эрх авах','Activate add-on' => 'Нэмэлтийг идэвхжүүлэх','Get more out of your checkout journey' => 'Төлбөр тооцооны аяллаасаа илүү ихийг аваарай','Test API key' => 'API түлхүүрийг турших','Guided setup' => 'Зааварчилгаатай тохиргоо','Options' => 'Сонголтууд','Set up layout and design on the <a href="%s">checkout options</a>.' => '<a href="%s">Төлбөрийн сонголтууд</a> дээр зохион байгуулалт болон дизайныг тохируулна уу.','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'Зочны төлбөр тооцоог идэвхжүүлэх болон/эсвэл <a href="%s">хэрэглэгчийн дансны тохиргоог</a> шалгах.','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'Оновчтой <a href="%1$s">сагс</a> , <a href="%2$s">баярлалаа</a> болон <a href="%3$s">захиалгын төлбөрийн</a> хуудсыг идэвхжүүлнэ үү.','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Google газрын зургаас <a href="%s">хаягийн автомат гүйцээлтийг</a> идэвхжүүлэх.','Enable multiple saved addresses with <a href="%s">address book</a>.' => '<a href="%s">Хаягийн дэвтэр</a> ашиглан олон хадгалагдсан хаягийг идэвхжүүлнэ үү.','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Таны суулгасан сэдэв эсвэл бусад залгаасуудад зориулсан ямар нэгэн <a href="%s">интеграцийн сонголтууд</a> байгаа эсэхийг шалгана уу.','Missing settings tab.' => 'Тохиргооны таб дутуу байна.','Getting started' => 'Эхлэх','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Гайхалтай! Таны төлбөр тооцооны хуудас одоо Fluid Checkout дээр ажиллаж байна.</strong> Эхлүүлэх хэдэн алхам энд байна:','Completed' => 'Дууссан','Send now' => 'Одоо илгээх','Auto-detect' => 'Автоматаар илрүүлэх','Afrikaans' => 'Африк','Albanian' => 'Албани','Amharic' => 'Амхарик','Arabic' => 'Араб хэл','Armenian' => 'Армени','Azerbaijani' => 'Азербайжан','Basque' => 'Баск','Belarusian' => 'Беларусийн','Bengali' => 'Бенгал','Bosnian' => 'Босни','Bulgarian' => 'Болгар','Burmese' => 'Бирм','Catalan' => 'Каталан','Chinese' => 'Хятад','Chinese (Simplified)' => 'Хятад (Хялбаршуулсан)','Chinese (Hong Kong)' => 'Хятад (Хонконг)','Chinese (Traditional)' => 'Хятад (Уламжлалт)','Croatian' => 'Хорват','Czech' => 'Чех','Danish' => 'Дани','Dutch' => 'Голланд','English' => 'Англи хэл','English (Australian)' => 'Англи (Австрали)','English (Great Britain)' => 'Англи (Их Британи)','Estonian' => 'Эстони','Farsi' => 'Фарс хэл','Finnish' => 'Финлянд','Filipino' => 'Филиппин','French' => 'Франц хэл','French (Canadian)' => 'Франц (Канад)','Galician' => 'Галисиан','Georgian' => 'Гүржийн','German' => 'Герман','Greek' => 'Грек','Gujarati' => 'Гужарати','Hebrew' => 'Еврей','Hindi' => 'Хинди','Hungarian' => 'Унгар','Icelandic' => 'Исланд','Indonesian' => 'Индонези','Italian' => 'Итали','Japanese' => 'Япон','Kannada' => 'Каннада','Kazakh' => 'Казак','Khmer' => 'Кхмер','Korean' => 'Солонгос','Kyrgyz' => 'Киргиз','Lao' => 'Лаос','Latvian' => 'Латви','Lithuanian' => 'Литва','Macedonian' => 'Македон','Malay' => 'Малай','Malayalam' => 'Малаялам','Marathi' => 'Марати','Mongolian' => 'Монгол','Nepali' => 'Непал','Norwegian' => 'Норвеги','Polish' => 'Польш','Portuguese' => 'Португали','Portuguese (Brazil)' => 'Португал (Бразил)','Portuguese (Portugal)' => 'Португал (Португал)','Punjabi' => 'Пенжаби','Romanian' => 'Румын','Russian' => 'Орос','Serbian' => 'Серби','Sinhalese' => 'Сингал','Slovak' => 'Словак','Slovenian' => 'Словени','Spanish' => 'Испани','Spanish (Latin America)' => 'Испани (Латин Америк)','Swahili' => 'Свахили хэл','Swedish' => 'Швед','Tamil' => 'Тамил','Telugu' => 'Телугу хэл','Thai' => 'Тайланд','Turkish' => 'Турк','Ukrainian' => 'Украйн','Urdu' => 'Урду','Vietnamese' => 'Вьетнам','Zulu' => 'Зулу','Google address autocomplete' => 'Google хаягийг автоматаар бөглөх','Google Places API version' => 'Google Places API хувилбар','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Google Places API-ийн аль хувилбарыг ашиглахаа сонгоно уу. Аль болох хурдан шинэ Places API руу шилжихийг зөвлөж байна.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => '2025 оны 3-р сарын 1-нээс эхлэн &quot;Places API (Шинэ)&quot;-г ашиглахыг бид зөвлөж байна. Google нь &quot;Places API (Уламжлалт)&quot; хувилбарыг Хуучин төлөвт шилжүүлэх бөгөөд энэ нь та энэ үйлчилгээг шинэ API түлхүүрүүдэд идэвхжүүлэх боломжгүй болох бөгөөд API-ийн тухайн хувилбар эцэстээ ашиглах боломжгүй болно гэсэн үг юм. Хуучин API ашиглаж байгаа одоо байгаа бүртгэлүүд тасалдалгүйгээр ажилласаар байж магадгүй.','(Recommended)' => '(Санал болгож байна)','Google API key' => 'Google API түлхүүр','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'Google API түлхүүрээ хуулж, энэ вэбсайт дээр ажиллаж байгааг баталгаажуулахын тулд тест товчийг ашиглана уу. Түлхүүр нь хүчинтэй бөгөөд таны домэйнд зөвшөөрөгдсөн эсэхийг шалгаарай, эс тэгвээс хаягийн талбар хаагдах бөгөөд ингэснээр үйлчлүүлэгчид захиалгаа гүйцэтгэх боломжгүй болж магадгүй.','Enable Google address autocomplete' => 'Google хаягийн автомат гүйцээлтийг идэвхжүүлэх','Enable address autocompletion using the Google Maps APIs.' => 'Google газрын зургийн API ашиглан хаягийн автомат гүйцээлтийг идэвхжүүлнэ үү.','Google API language' => 'Google API хэл','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Энэ хэлийг Google Places API хаягийн саналуудыг харуулахад ашиглах бөгөөд хаягууд нь энэ хэлээр автоматаар гүйцээгдэнэ.','Result types' => 'Үр дүнгийн төрлүүд','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Илүү сайн тохирох үр дүн өгдөг аливаа төрлийн үр дүнг хүлээн авахын тулд хоосон үлдээнэ үү. <a href="%s" target="_blank">Дэлгэрэнгүй мэдээллийг баримт бичгээс үзнэ үү</a> .<br> Хаягийн автоматаар бөглөх талбаруудад буцаахын тулд 5 хүртэлх төрлийн хаягийн хайлтын үр дүнг сонгоно уу.<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">Дэмжигдсэн төрлүүдийн</a> талаар дэлгэрэнгүй мэдээлэл авахыг хүсвэл Google газрын зургийн баримт бичигт зочилно уу.','Result types (Legacy API)' => 'Үр дүнгийн төрлүүд (Legacy API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Places API (Legacy) ашиглах үед ямар төрлийн хаягийн хайлтын үр дүнг харуулах вэ.<br> <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">Дэмжигдсэн төрлүүдийн</a> талаар дэлгэрэнгүй мэдээлэл авахыг хүсвэл Legacy Google Places API-ийн баримт бичигт зочилно уу.','Company fields' => 'Компанийн талбарууд','Enable autocomplete for the company name if available' => 'Хэрэв боломжтой бол компанийн нэрийн автоматаар бөглөхийг идэвхжүүлнэ үү','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Google газрын зургийн API-с буцаахад компанийн нэрийн мэдээллээр компанийн талбарыг автоматаар гүйцээхийг идэвхжүүлнэ үү.','Business search' => 'Бизнесийн хайлт','Enable search for businesses in the company field' => 'Компанийн талбарт бизнесийн хайлтыг идэвхжүүлэх','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'Компанийн талбарт бичих үед бизнестэй холбоотой хаягийн саналыг идэвхжүүлж, дараа нь саналуудаас бизнесийг сонгоход бүх хаягийн талбарыг автоматаар бөглөнө үү.','Company result types' => 'Компанийн үр дүнгийн төрлүүд','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Автоматаар бөглөх компанийн талбаруудад харуулах 5 хүртэлх төрлийн хаягийн хайлтын үр дүнг сонгоно уу.<br> Санал болгож буй утга нь ихэнх төрлийн бизнесийг багтаасан <code>establishment</code> юм.<br> Бизнестэй холбоогүй үр дүнг оруулаад ямар ч төрлийн үр дүнг хүлээн авахын тулд хоосон үлдээнэ үү.<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">Дэмжигдсэн төрлүүдийн</a> талаар дэлгэрэнгүй мэдээлэл авахыг хүсвэл Google газрын зургийн баримт бичигт зочилно уу.','Google logo' => 'Google-ийн лого','Show text and logo "Powered by Google"' => '&quot;Google-ийн хүчээр ажилладаг&quot; текст болон логог харуулах','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'Тэмдэглэсэн үед хаягийн автоматаар бөглөх санал болгох цонхны доод хэсэгт &quot;Google-ийн хүчээр ажилладаг&quot; гэсэн текст болон лого гарч ирнэ.','Brasil API address autocomplete' => 'Бразилийн API хаягийг автоматаар гүйцээх','Brasil API' => 'Бразилийн API','Enable Brasil API address autocomplete for CEP fields' => 'CEP талбаруудад зориулсан Brasil API хаягийн автомат гүйцээлтийг идэвхжүүлэх','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'CEP/Шуудангийн код талбарыг ашиглан хаягуудыг авах болон автоматаар бөглөхийн тулд Brasil API ашиглана уу. Зөвхөн Бразилийн хаягуудад хамааралтай.','API version' => 'API хувилбар','Choose which version of the Brasil API CEP method to use.' => 'Brasil API CEP аргын аль хувилбарыг ашиглахаа сонгоно уу.','Address book migration' => 'Хаягийн номын шилжилт','WooCommerce addresses' => 'WooCommerce хаягууд','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'WooCommerce-ээс одоо байгаа тээвэрлэлтийн болон төлбөрийн хаягийг хэрэглэгчийн хаягийн дэвтэрт хуулж ав.','Enable the address book feature' => 'Хаягны дэвтрийн функцийг идэвхжүүлэх','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Үйлчлүүлэгчдэд олон хаяг хадгалах, тээвэрлэлт болон төлбөр тооцоонд ашиглах анхдагч хаягийг тодорхойлох боломжийг олгоно.','Address labels' => 'Хаягийн шошго','Allow customers to add a custom label for each address' => 'Үйлчлүүлэгчдэд хаяг бүрт тусгай шошго нэмэхийг зөвшөөрөх','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'Хаягийн шошго нь үйлчлүүлэгчдэд хадгалсан хаягаа (жишээ нь: &quot;Ээжийн байшин&quot;) ялгахад хялбар болгодог. Хаягийн шошго нь үйлчлүүлэгчдэд хувийнх бөгөөд захиалгын дэлгэрэнгүй хуудас эсвэл нэхэмжлэх дээр харагдахгүй эсвэл хэвлэгдээгүй болно.','Display layout' => 'Дэлгэцийн зохион байгуулалт','Choose how saved addresses are displayed at checkout and on the cart.' => 'Хадгалсан хаягуудыг төлбөр тооцоо хийх үед болон сагсан дээр хэрхэн харуулахыг сонгоно уу.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'Төлбөр тооцоо хийх болон сагсанд хүчинтэй. Дансны хуудсан дээр хадгалагдсан хаягууд үргэлж картын загварыг ашигладаг.','Address cards' => 'Хаягийн картууд','Address list' => 'Хаягийн жагсаалт','Dropdown field' => 'Унжих цэсний талбар','Address search' => 'Хаяг хайх','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'Үйлчлүүлэгч дор хаяж энэ тооны хадгалсан хаягтай үед хаягийн хайлтын шүүлтүүрийг урд хэсэгт харуулна.','Not used when display layout is set to dropdown field.' => 'Дэлгэцийн байршлыг унах талбарт тохируулсан үед ашиглахгүй.','Addresses' => 'Хаягууд','Enable cart page optimizations to see more options' => 'Илүү олон сонголтыг харахын тулд сагсны хуудасны оновчлолыг идэвхжүүлнэ үү','Sticky order summary' => 'Наалдамхай захиалгын хураангуй','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Сагсны хуудсан дээр купоны кодын хэсгийг харуулах байрлалыг сонгоно уу. Зөвхөн AJAX сагс идэвхжсэн үед болон WooCommerce тохиргоонд купоны кодын хэрэглээг идэвхжүүлсэн тохиолдолд л хүчинтэй.','Layout of cross-sell' => 'Хөндлөн борлуулалтын зохион байгуулалт','Cross-sells displayed' => 'Харилцан борлуулалтыг харуулсан','Items' => 'Зүйлс','Cart page optimization' => 'Сагсны хуудасны оновчлол','Give your cart the same clear, conversion-focused layout as your checkout.' => 'Сагсандаа төлбөр тооцооныхоо адил тодорхой, хөрвүүлэлтэд чиглэсэн загварыг өгөөрэй.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'Тогтвортой худалдан авалтын аялал хийхийн тулд сагсны загварыг төлбөр тооцооны хуудастай тохируулна уу.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'Сагсыг үргэлж шинэчилж байх, тоо хэмжээ өөрчлөгдөхөд бүтэн хуудсыг дахин ачаалахгүй байх.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Купоны код, хүргэлт болон кросс-борлуулалтыг хамгийн сайн хөрвүүлэх боломжтой газарт нь яг таг байрлуул.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Гүйлгэх үедээ захиалгын хураангуйг харагдахуйц байлгаж, худалдан авагчдад баталгаа хэрэгтэй газруудад итгэлцлийн тэмдэг нэмж оруулаарай.','Columns' => 'Баганууд','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => '<em>&quot;Хуваах&quot;</em> загвартай <em>&quot;1 багана&quot;</em> байрлалыг ашиглах үед хуудасны хажуугийн самбарын виджетийн хэсэг идэвхтэй байгаа тохиолдолд л баруун багана харагдана (Хажуугийн самбар, Сагсны хажуугийн самбар эсвэл Хүлээн авсан захиалгын хажуугийн самбар). Үгүй бол хуудас нь Хуваах хэв маягтай ганц багана хэвээр үлдэнэ.','Split column background' => 'Баганын дэвсгэрийг хуваах','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'Хуваах дизайны хоёрдогч баганын дэвсгэр өнгийг сонгоно уу. Захиалгын хураангуй дэвсгэр өнгийг ашиглахын тулд хоосон үлдээнэ үү.','Page templates' => 'Хуудасны загварууд','Checkout template' => 'Төлбөрийн загвар','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Төлбөр тооцооны үеэр анхаарал сарниулах зүйл багатай тул санал болгож байна. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Сагс хаях талаарх судалгааг уншина уу</a> .','Sticky progress bar' => 'Наалдамхай явцын мөр','Progress bar style' => 'Прогрессийн мөрийн хэв маяг','Order totals' => 'Нийт захиалгын дүн','Background color' => 'Дэвсгэр өнгө','Action link' => 'Үйлдлийн холбоос','Mobile order summary' => 'Мобайл захиалгын хураангуй','Mobile initial state' => 'Мобайл анхны төлөв','Enable editing cart items at checkout' => 'Төлбөр тооцоо хийх үед сагсны зүйлсийг засахыг идэвхжүүлэх','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Хэрэглэгчдэд бүтээгдэхүүний тоо хэмжээг өөрчлөх эсвэл бараа бүтээгдэхүүнийг төлбөр тооцооны хуудсан дээрээс шууд хасах боломжийг олгоно.','Cart item errors' => 'Сагсны барааны алдаа','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Зөвхөн купоны кодыг төлбөр тооцоо эсвэл сагсны хуудсан дээр тусдаа хэсэг болгон харуулсан үед болон WooCommerce тохиргоонд купоны кодыг ашиглахыг идэвхжүүлсэн тохиолдолд л хүчинтэй.','Coupon codes position' => 'Купоны кодын байршил','Apply coupon button' => 'Купон хэрэглэх товчлуур','Select style of the "apply coupon" button.' => '&quot;Купон хэрэглэх&quot; товчлуурын хэв маягийг сонгоно уу.','Address line 2' => 'Хаягийн мөр 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'Энэ тохиргоог Тооцоо хийх болон Орон нутгийн хүргэлтийн хэсгүүдэд хуваалцдаг. Орон нутгийн хүргэлтийн хэсэгт Тээвэрлэлт/Авах сонголт нь тээвэрлэлтийн аргын хэсэгт (хаягийн өмнө) эсвэл тусдаа хэсэг (дараа) хэлбэрээр харагдах эсэхийг шийддэг.','Customer accounts' => 'Харилцагчийн данс','Guest checkout' => 'Зочны төлбөр тооцоо','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'WooCommerce бүртгэлийн тохиргооны хуудаснаас зочны бүртгэл, нэвтрэх болон бүртгэл үүсгэх сонголтуудыг хийж болно. Эдгээрийг таны тав тухтай байдлыг хангах үүднээс энд удирддаг тул та тохиргооны профайл бүрт өөр өөр утгыг ашиглаж болно.','Allow customers to checkout without an account' => 'Үйлчлүүлэгчдэд дансгүйгээр төлбөр тооцоо хийх боломжийг олгох','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => 'Хэрэглэгчдээс төлбөр тооцооны үеэр бүртгэл үүсгэх эсвэл нэвтрэхийг хүсэхгүй байхаар <strong>зөвлөж байна</strong> , учир нь энэ нь хөрвүүлэлтийн түвшинг бууруулж болзошгүй юм.','When disabled, customers must log in or create an account to complete the purchase.' => 'Идэвхгүй болгосон үед худалдан авалтаа дуусгахын тулд хэрэглэгчид нэвтрэх эсвэл бүртгэл үүсгэх шаардлагатай.','Login at checkout' => 'Төлбөр тооцоо хийх үед нэвтэрнэ үү','Enable log-in during checkout' => 'Төлбөр тооцоо хийх үед нэвтрэхийг идэвхжүүлэх','Show a link for returning customers to log in from the checkout page.' => 'Төлбөр тооцооны хуудаснаас буцаж ирсэн үйлчлүүлэгчдэд нэвтрэх холбоосыг харуулах.','Account creation' => 'Бүртгэл үүсгэх','Allow customers to create an account during checkout' => 'Төлбөр тооцооны үеэр хэрэглэгчдэд данс үүсгэхийг зөвшөөрөх','Allow customers to create an account from the My account page' => 'Миний бүртгэл хуудаснаас хэрэглэгчдэд бүртгэл үүсгэхийг зөвшөөрөх','Customers can register a new account from the My account page.' => 'Үйлчлүүлэгчид Миний бүртгэл хуудаснаас шинэ данс бүртгүүлэх боломжтой.','Username' => 'Хэрэглэгчийн нэр','Generate from customer\'s name' => 'Үйлчлүүлэгчийн нэрээс үүсгэх','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => 'Хэрэглэгчдээс төлбөр тооцооны үеэр хэрэглэгчийн нэр сонгохыг хүсэхгүй байхаар <strong>зөвлөж байна</strong> , учир нь энэ нь хөрвүүлэлтийн түвшинг бууруулж болзошгүй юм.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'Хэрэглэгчийн нэр нь хэрэглэгчийн нэрээс эсвэл нэрийг ашиглах боломжгүй үед имэйл хаягаас үүсгэгддэг.','Password' => 'Нууц үг','Send password setup link' => 'Нууц үг тохируулах холбоос илгээх','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => 'Үйлчлүүлэгчдээс төлбөр тооцооны үеэр нууц үг тохируулахыг хүсэхгүй байхаар <strong>зөвлөж байна</strong> , учир нь энэ нь хөрвүүлэлтийн түвшинг бууруулж болзошгүй юм.','Customers receive an email to create their password securely.' => 'Хэрэглэгчид нууц үгээ аюулгүй үүсгэхийн тулд имэйл хүлээн авдаг.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Бүртгэлтэй үйлчлүүлэгчдэд нэвтрэхгүйгээр төлбөр тооцоогоо дуусгах боломжийг олгож, холбоо барих мэдээлэл таарсан тохиолдолд захиалгыг одоо байгаа бүртгэлтэйгээ холбоно уу.','Existing account message' => 'Одоо байгаа бүртгэлийн мессеж','Let customers create an account after placing their order, from the thank you page.' => 'Талархлын хуудаснаас захиалгаа өгсний дараа үйлчлүүлэгчдэд бүртгэл үүсгэх боломжийг олгоорой.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'Энэ хэсэгт байгаа сонголтууд нь зочны төлбөр тооцоо болон данс тохируулах функцийг идэвхжүүлсэн үед боломжтой. Дээрх хоёр функцийг идэвхжүүлж, данс үүсгэхийг хойшлуулна уу.','Enable delayed account creation' => 'Хойшлуулсан бүртгэл үүсгэхийг идэвхжүүлэх','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'Зочны төлбөр тооцоо болон данс тохируулахыг идэвхжүүлсэн үед хойшлуулсан данс үүсгэхийг идэвхжүүлнэ үү.','Section position' => 'Хэсгийн байрлал','Before customer details section' => 'Үйлчлүүлэгчийн мэдээллийн хэсгийн өмнөх хэсэг','After customer details section' => 'Үйлчлүүлэгчийн мэдээллийн дараах хэсэг','Account creation benefits' => 'Данс үүсгэх давуу талууд','Leaving the field empty will display the default text.' => 'Талбарыг хоосон орхивол анхдагч текстийг харуулна.','Inline buttons' => 'Шугамын товчлуурууд','Required fields' => 'Заавал бөглөх талбарууд','Enable gift message fields at checkout' => 'Төлбөр тооцоо хийх үед бэлгийн мессежийн талбаруудыг идэвхжүүлнэ үү','Expanded gift message' => 'Өргөтгөсөн бэлгийн мессеж','Display gift message field always expanded' => 'Бэлгийн мессежийн талбарыг үргэлж дэлгэдэг харуулах','Gift message in order details' => 'Захиалгын дэлгэрэнгүй мэдээлэл дэх бэлгийн мессеж','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'Энэ хэсэгт одоогоор ямар ч интеграцчлал байхгүй байна. Залгаас болон сэдэв тус бүртэй холбоотой сонголтууд нь зөвхөн тухайн залгаас эсвэл загвар идэвхжсэн үед л энд гарч ирнэ.','Phone fields' => 'Утасны талбарууд','Field visibility' => 'Талбайн харагдах байдал','Field position' => 'Талбайн байрлал','Phone country code & validation' => 'Утасны улсын код болон баталгаажуулалт','Country' => 'Улс','Enable country on phone fields' => 'Утасны талбарт улсыг идэвхжүүлэх','Filter countries for shipping or billing' => 'Тээвэрлэлт эсвэл төлбөр тооцооны улсуудыг шүүх','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Утасны талбар бүрийн улс сонгогчийг дэлгүүртээ тээвэрлэлт эсвэл төлбөр тооцоо хийхийг зөвшөөрсөн улсуудаар хязгаарлаарай.','Validation' => 'Баталгаажуулалт','Enable simple validation based on country rules' => 'Улс орны дүрэмд үндэслэн энгийн баталгаажуулалтыг идэвхжүүлэх','Checks that the phone number is valid for the selected country, including country code and length.' => 'Сонгосон улсад утасны дугаар хүчинтэй эсэхийг улсын код болон уртыг оруулан шалгана.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'Сонгосон улсад хүчинтэй гар утас, суурин утас эсвэл бусад хүлээн зөвшөөрөгдсөн төрөл мөн эсэхийг илүү нарийн шалгана уу. Зарим хүчинтэй дугаарыг татгалзаж магадгүй.','Validation types' => 'Баталгаажуулалтын төрлүүд','Placeholders' => 'Орлуулагчид','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'Одоогоор удирдах лицензийн түлхүүр алга байна. Лицензийн түлхүүрүүд нь Fluid Checkout залгаас эсвэл нэмэлт идэвхтэй үед энд гарч ирнэ.','Default delivery type' => 'Хүргэлтийн анхдагч төрөл','Choose which delivery type will be selected by default.' => 'Анхдагчаар ямар хүргэлтийн төрлийг сонгохоо сонгоно уу.','Shipping zone fields' => 'Тээврийн бүсийн талбарууд','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Орон нутгийн хүргэлтийн бүсийн шүүлтүүрийн талбаруудад аль талбаруудыг харуулахыг сонгоно уу. Боломжтой бүх сонголтыг харуулахын тулд хоосон үлдээнэ үү.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Эдгээр талбарууд нь орон нутгийн хүргэлтийн аргуудын шүүлтүүр хэлбэрээр харагдах болно. Хэрэв нийцтэй нэмэлт өргөтгөлүүд зөв ажиллахыг шаарддаг бол зарим талбарууд энд сонгоогүй ч төлбөр тооцооны үеэр гарч ирж магадгүй.','Order shipping address' => 'Захиалгын хүргэлтийн хаяг','Order pay page optimization' => 'Захиалгын төлбөрийн хуудасны оновчлол','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'Төлбөр төлөөгүй захиалгад төлбөр тооцоотой адил тодорхой, хөрвүүлэлтэд чиглэсэн загварыг өг.','Optimize the layout of the order pay page for orders pending payment.' => 'Төлбөр хүлээгдэж буй захиалгын төлбөрийн хуудасны бүтцийг оновчтой болгох.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'Тогтвортой худалдан авалтын аялал хийхийн тулд захиалгын төлбөрийн туршлагыг төлбөр тооцооныхоо туршлагатай тохируулна уу.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Төлбөр төлөхөөсөө өмнө худалдан авагчдад баталгаа өгөх шаардлагатай газарт итгэлцлийн тэмдэг, тэмдэг нэмээрэй.','Thank you page optimization' => 'Хуудасны оновчлолд баярлалаа','Make the thank you page and order details clearer for customers after they buy.' => 'Худалдан авалт хийсний дараа үйлчлүүлэгчдэд талархлын хуудас болон захиалгын дэлгэрэнгүй мэдээллийг илүү тодорхой болго.','Optimize the thank you page and account order details with a clearer layout.' => 'Талархлын хуудас болон дансны захиалгын дэлгэрэнгүй мэдээллийг илүү тодорхой зохион байгуулалтаар оновчтой болго.','Show order status progress, actions, downloads, and notes where they make sense.' => 'Захиалгын төлөвийн явц, үйлдэл, татан авалт болон тэмдэглэлийг утга учиртай хэсэгт нь харуулна уу.','Customize order details sections on email notifications.' => 'Имэйл мэдэгдэл дээрх захиалгын дэлгэрэнгүй хэсгүүдийг өөрчлөх.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Худалдан авалт хийсний дараа худалдан авагчдад баталгаа хэрэгтэй газарт итгэлцлийн тэмдэг, тэмдэг нэмээрэй.','Email notifications' => 'Имэйл мэдэгдэл','Enable thank you page and order details optimizations to see more options' => 'Илүү олон сонголтыг харахын тулд талархлын хуудас болон захиалгын дэлгэрэнгүй оновчлолыг идэвхжүүлнэ үү','Use wide layout on thank you page' => 'Талархлын хуудсан дээр өргөн хүрээтэй загвар ашиглана уу','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Эдгээр сонголтууд нь талархлын хуудсанд нөлөөлж, захиалгын дэлгэрэнгүй мэдээллийг дансны хуудас болон имэйл мэдэгдлээс харна.','Save settings' => 'Тохиргоог хадгалах','Docs' => 'Баримт бичиг','Cart' => 'Сагс','Thank you' => 'Баярлалаа','Address autocomplete' => 'Хаягийг автоматаар бөглөх','Trust badges' => 'Итгэмжлэлийн тэмдэг','You do not have permission to save these settings.' => 'Танд эдгээр тохиргоог хадгалах зөвшөөрөл байхгүй байна.','Invalid save request.' => 'Хадгалах хүсэлт буруу байна.','Your settings have been saved.' => 'Таны тохиргоо хадгалагдсан.','Saving...' => 'Хадгалж байна...','Settings could not be saved. Please try again.' => 'Тохиргоог хадгалж чадсангүй. Дахин оролдоно уу.','Dismiss notice' => 'Мэдэгдлийг хаах','Open settings menu' => 'Тохиргооны цэсийг нээх','Close settings menu' => 'Тохиргооны цэсийг хаах','Preview' => 'Урьдчилан харах','Expand preview' => 'Урьдчилж харахыг дэлгэх','Collapse preview' => 'Урьдчилан харахыг буулгах','Show header and footer' => 'Толгой болон доод хэсгийг харуулах','Hide header and footer' => 'Толгой болон доод хэсгийг нуух','Page preview' => 'Хуудасны урьдчилсан тойм','Preview viewport' => 'Урьдчилан харах цонх','Tablet' => 'Таблет','Desktop' => 'Ширээний компьютер','Preview width' => 'Урьдчилан харах өргөн','Decrease width' => 'Өргөнийг багасгах','Preview width in pixels' => 'Урьдчилан харах өргөнийг пикселээр илэрхийлэх','Increase width' => 'Өргөнийг нэмэгдүүлэх','Preview as' => 'Урьдчилан харах','Guest' => 'Зочин','Logged in' => 'Нэвтэрсэн','Preview page' => 'Урьдчилан харах хуудас','Expand preview for a closer look' => 'Илүү дэлгэрэнгүй харахын тулд урьдчилж харахыг дэлгэнэ үү','Available with %s.' => '%s-тэй хамт ашиглах боломжтой.','Turn them on' => 'Тэдгээрийг асаана уу','Optimizations for this page are turned off. %s to preview the page.' => 'Энэ хуудасны оновчлолыг унтраасан байна. Хуудсыг урьдчилан харахын тулд %s дарна уу.','%s preview' => '%s урьдчилж харах','Isolated session · nothing is saved' => 'Тусгаарлагдсан хуралдаан · юу ч хадгалагдаагүй','Usage tracking' => 'Хэрэглээний хяналт','Plugin settings' => 'Нэмэлт өргөтгөлийн тохиргоо','Coming soon' => 'Удахгүй','Utilities' => 'Хэрэгслүүд','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => '<code>select2</code> ын оронд <code>TomSelect</code> унждаг бүрэлдэхүүн хэсгүүдийг ашиглана уу','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect нь Select2-оос алдаа гарах магадлал багатай, мөн ижил функцийг санал болгодог энгийн унждаг цэсний сонголтын бүрэлдэхүүн хэсэг юм.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'Жижиг төхөөрөмж дээрх маягтын талбаруудтай харилцах үед автоматаар томруулахаас зайлсхийхийн тулд энэ залгаасаар оновчтой болгосон хуудсан дээрх маягтын талбарууд доторх фонтын хэмжээг 16 пиксел болгож тохируулна.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'Фонтын хэмжээ 16 пикселээс бага байх үед Safari болон бусад хөтөч нь гар утасны төхөөрөмж дээр текстийг уншихад хялбар болгохын тулд автоматаар томруулж магадгүй.','Enable script processing tracking on the browser console.' => 'Хөтчийн консол дээр скрипт боловсруулалтын хяналтыг идэвхжүүлэх.','Unminified assets' => 'Багасгаагүй хөрөнгө','Google Maps scripts' => 'Google газрын зургийн скриптүүд','Do not remove duplicate Google Maps scripts' => 'Давхардсан Google газрын зургийн скриптүүдийг бүү устга','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Идэвхжүүлсэн үед Google газрын зургийн давхардсан скриптүүд УСТГАГДАХГҮЙ бөгөөд энэ нь алдаа болон гүйцэтгэлийн асуудал үүсгэж болзошгүй. Зөвхөн алдааг олж засварлах үедээ энэ сонголтыг ашиглаарай.','Widget areas' => 'Виджетийн хэсгүүд','Last step on mobile' => 'Гар утсан дээрх сүүлийн алхам','Display widgets only at last step on mobile' => 'Гар утсан дээр зөвхөн сүүлийн алхам дээр виджетүүдийг харуулах','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'Гар утасны төхөөрөмж дээр зөвхөн сүүлийн төлбөрийн алхамыг харах үед төлбөрийн итгэмжлэлийн тэмдгийн виджетүүдийг харуулах','Standard' => 'Стандарт','VAT number field' => 'НӨАТ-ын дугаарын талбар','Add a VAT number field to the billing form.' => 'Төлбөрийн маягтанд НӨАТ-ын дугаарын талбар нэмнэ үү.','Field label' => 'Талбарын шошго','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'НӨАТ-ын дугаарын талбарын шошгыг тохируулна уу (жишээ нь НӨАТ-ын дугаар). Олон хэлний вэбсайтууд дээр энэ талбарыг хоосон орхиж, анхны мөрийг орчуулсан нь дээр.','VAT Number' => 'НӨАТ-ын дугаар','EU-VAT' => 'Европын Холбооны НӨАТ','Enable the VAT number field to see more options' => 'Илүү олон сонголтыг харахын тулд НӨАТ-ын дугаарын талбарыг идэвхжүүлнэ үү','VAT validation' => 'НӨАТ-ын баталгаажуулалт','Validate VAT number field for EU-VAT during checkout' => 'Төлбөр тооцоо хийх үед ЕХ-НӨАТ-ын дугаарын талбарыг баталгаажуулна уу','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Өгөгдсөн НӨАТ-ын дугаар нь Европын VIES мэдээллийн санд (НӨАТ-ын мэдээллийн солилцооны систем) бүртгэгдсэн хүчинтэй НӨАТ-ын дугаар мөн эсэхийг шалгана.','Shop VAT number' => 'Дэлгүүрийн НӨАТ-ын дугаар','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'Европын Холбооны НӨАТ-ын баталгаажуулалт хүсэхэд ашигласан бөгөөд нэхэмжлэх дээр хэвлэсэн дэлгүүрийн НӨАТ-ын дугаар.<br> VIES зөвлөлдөх үр дүн нягтлан бодох бүртгэлийн зорилгоор хүчингүй байж магадгүй тул <strong>дэлгүүрийн НӨАТ-ын дугаараа нэмэхийг бид танд зөвлөж байна</strong> .<br> Өөрөөр хэлбэл: <code>ATU99999999</code> эсвэл <code>EE999999999</code> .','Reverse charge' => 'Урвуу цэнэг','Apply reverse charge mechanism' => 'Урвуу цэнэглэх механизмыг хэрэглэнэ','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Татварын хувь хэмжээг тэг болгож тохируулж, хэрэглэгчийн НӨАТ-ын дугаар хүчинтэй үед нэхэмжлэх дээр &quot;Урвуу төлбөр&quot; гэж харуулна уу. Дэлгүүрийн улсаас хамааран өөр &quot;Урвуу төлбөр&quot; гэсэн текст шаардагдаж магадгүй.','Same country' => 'Нэг улс','Apply reverse charge mechanism for transactions in the shop country:' => 'Дэлгүүрийн улс дахь гүйлгээнд урвуу төлбөрийн механизмыг хэрэглэнэ үү:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Дэлгүүртэй ижил улсад байгаа компаниудын хоорондох гүйлгээнд урвуу төлбөрийн механизмыг хэрэгжүүлэх боломжийг олгодог.','Reverse charge exceptions' => 'Урвуу төлбөрийн үл хамаарах зүйлс','Select additional countries to skip applying the reverse charge mechanism.' => 'Урвуу төлбөрийн механизмыг хэрэглэхийг алгасах нэмэлт улсуудыг сонгоно уу.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'Хүчинтэй НӨАТ-ын дугаар өгсөн байсан ч эдгээр улсаас ирсэн захиалгад татвар ногдуулна.','Reverse charge label on invoices' => 'Нэхэмжлэх дээрх урвуу төлбөрийн шошго','Set the label of "reverse charge" on the checkout page and order details.' => 'Төлбөр тооцооны хуудас болон захиалгын дэлгэрэнгүй мэдээлэл дээр &quot;урвуу төлбөр&quot; гэсэн шошгыг тохируулна уу.','Reverse charge text on invoices' => 'Нэхэмжлэх дээрх урвуу төлбөрийн текст','Set the label of "reverse charge" text on invoices.' => 'Нэхэмжлэх дээр &quot;урвуу төлбөр&quot; гэсэн текстийн шошгыг тохируулна уу.','Tax to be paid on reverse charge basis' => 'Буцаах төлбөрийн үндсэн дээр төлөх татвар','Company name' => 'Компанийн нэр','Autocomplete company name from VAT number' => 'НӨАТ-ын дугаараас компанийн нэрийг автоматаар бөглөнө үү','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Харилцагчийн өгсөн хүчинтэй НӨАТ-ын дугаар дээр үндэслэн төлбөр тооцооны компанийн нэрийг бөглөнө үү.','Company name editing' => 'Компанийн нэрийг засварлах','Allow editing of auto-filled company name' => 'Автоматаар бөглөсөн компанийн нэрийг засахыг зөвшөөрөх','When enabled, customers can change the company name associated with the provided VAT number.' => 'Идэвхжүүлсэн үед хэрэглэгчид өгөгдсөн НӨАТ-ын дугаартай холбоотой компанийн нэрийг өөрчлөх боломжтой.','EU-VAT for digital goods' => 'Дижитал барааны ЕХ-ны НӨАТ','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => '2015 оны 1-р сарын 1-нээс эхлэн дижитал барааны талаарх Европын Холбооны НӨАТ-ын журамд өөрчлөлт оруулсан бөгөөд энэ нь зөвхөн B2C гүйлгээнд нөлөөлсөн. Дижитал барааны НӨАТ-ыг хэрэглэгчийн байршлаар тооцох ёстой бөгөөд үүнийг нотлох баримт (IP хаяг болон төлбөрийн хаяг) цуглуулах шаардлагатай.','Tax classes for digital goods' => 'Дижитал барааны татварын ангилал','Select some tax classes' => 'Зарим татварын ангиллыг сонгоно уу','Location evidence' => 'Байршлын нотолгоо','Collect customer\'s location evidence' => 'Үйлчлүүлэгчийн байршлын нотлох баримтыг цуглуулах','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'IP хаягийг хадгалж, харилцагчийн төлбөрийн хаягтай харьцуулан баталгаажуулна. Хэрэв харилцагчийн төлбөрийн хаяг болон IP хаяг нь таарахгүй байвал төлбөрийн хуудсан дээрх тэмдэглэгээний нүдийг чагталж төлбөрийн хаягаа баталгаажуулах ёстой.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'Энэ сонголтыг Шингэн Төлбөр Тооцоо хэсэгт удирддаг. <a href="%s">Үүнийг Харилцагчийн дансны тохиргоо хэсэгт өөрчилнө үү</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'Энэ сонголтыг Fluid Checkout хэсэгт удирддаг. Үүнийг Fluid Checkout &gt; Хэрэглэгчийн бүртгэл дотроос өөрчилнө үү.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Энэ сонголтыг Fluid Checkout хэсэгт удирддаг. Fluid Checkout идэвхжсэн үед хүргэлтийн очих газар нь үргэлж &quot;Хэрэглэгчийн тээвэрлэлтийн хаягийн анхдагч&quot; гэж тохируулагдсан байдаг. Үйлчлүүлэгчид төлбөр тооцооны үеэр өөр тээвэрлэлт болон төлбөр тооцооны хаягийг өгөх боломжтой хэвээр байна.<br><br> <a href="%s">Fluid Checkout тохиргоонд</a> анхдагч төлбөрийн хаягийг тээвэрлэлтийн хаягтай ижил байхаар тохируулах сонголт байдаг.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Энэ сонголтыг Fluid Checkout хэсэгт удирддаг. Fluid Checkout идэвхжсэн үед хүргэлтийн очих газар нь үргэлж &quot;Хэрэглэгчийн тээвэрлэлтийн хаягийн анхдагч&quot; гэж тохируулагдсан байдаг. Үйлчлүүлэгчид төлбөр тооцооны үеэр өөр тээвэрлэлт болон төлбөр тооцооны хаягийг өгөх боломжтой хэвээр байна.<br><br> WooCommerce &gt; Тохиргоо &gt; Fluid Checkout хэсэгт анхдагч төлбөрийн хаягийг тээвэрлэлтийн хаягтай ижил байхаар тохируулах сонголтыг авах боломжтой.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Эдгээр тохиргоог WP Admin &gt; Fluid Checkout &gt; Settings руу шилжүүлсэн.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'Энэхүү WooCommerce Тохиргооны таб нь хуучирсан бөгөөд Fluid Checkout 6.0 дээр устах болно.','Go to settings page' => 'Тохиргооны хуудас руу очих','Hide this tab permanently' => 'Энэ табыг бүрмөсөн нуух','Close' => 'Хаах','PRO feature' => 'PRO функц','Other plugins' => 'Бусад нэмэлт өргөтгөлүүд','Install add-on' => 'Нэмэлтийг суулгах','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => 'Эдгээр сонголтуудын түгжээг тайлахын тулд <a target="_blank" href="%1$s">%2$s аваарай</a> .','Add-on' => 'Нэмэлт','View documentation' => 'Баримт бичгийг харах','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'Хүсэлтүүд нь нэвтэрсэн WordPress хэрэглэгчийг шаарддаг. Одоогийн хэрэглэгчийн өгөгдлийг ашиглахын тулд user_id-г орхих эсвэл дуудлага хийгч тухайн хэрэглэгчийг засах боломжтой үед өөр бүртгэлийг чиглүүлэхийн тулд user_id-г дамжуулна уу (edit_user боломж). Баталгаажаагүй хүсэлтүүд fc_api_forbidden буцаана. Хүчингүй user_id нь fc_api_user_not_found буцаана.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 нь боловсруулагч нь ашигтай ачааллыг буцаах үед { &quot;data&quot;: { ... } } байна.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'Ачаалал байхгүй үед (жишээ нь DELETE) HTTP 200 нь {&quot;success&quot;: true } байна.','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'Алдаа нь WP_Error (код, мессеж, өгөгдөл.статус)-аас WordPress REST алдаа JSON-г буцаадаг. Утасны кодууд fc_api_* угтварыг ашигладаг.','Forbidden access.' => 'Хориглосон хандалт.','Target user was not found.' => 'Зорилтот хэрэглэгч олдсонгүй.','This feature is not available.' => 'Энэ функц боломжгүй байна.','A required address field is missing.' => 'Заавал бөглөх хаягийн талбар дутуу байна.','Postcode or ZIP is invalid.' => 'Шуудангийн код эсвэл шуудангийн код буруу байна.','Phone number is invalid.' => 'Утасны дугаар буруу байна.','State or county is invalid.' => 'Муж эсвэл тойрог хүчингүй байна.','Country is invalid or has no address fields.' => 'Улс буруу эсвэл хаягийн талбаргүй байна.','The request could not be processed.' => 'Хүсэлтийг боловсруулж чадсангүй.','Back to previous step' => 'Өмнөх алхам руу буцах','Skip to settings' => 'Тохиргоо руу алгасах','Start over and return to the first guided setup step' => 'Дахин эхлүүлээд эхний зааварчилгаатай тохиргооны алхам руу буцна уу','Start over' => 'Дахин эхлүүлэх','Please complete all sub-steps before continuing.' => 'Үргэлжлүүлэхээсээ өмнө бүх дэд алхмуудыг гүйцэтгэнэ үү.','Expand' => 'Өргөжүүлэх','Collapse' => 'Хураах','Skip' => 'Алгасах','Mark as complete' => 'Дууссан гэж тэмдэглэх','Mark as incomplete' => 'Дуусаагүй гэж тэмдэглэх','View full-size image: %s' => 'Бүтэн хэмжээтэй зургийг харах: %s','Full-size setup guide image' => 'Бүрэн хэмжээний тохиргооны гарын авлагын зураг','Close image' => 'Зургийг хаах','Fluid Checkout Guided Setup' => 'Шингэн шалгах зааварчилгаатай тохиргоо','All set' => 'Бүх зүйл бэлэн','You do not have permission to access this page.' => 'Та энэ хуудсанд хандах эрхгүй байна.','Go to step %1$d: %2$s' => '%1$d алхам руу очих: %2$s','Finish & go to settings' => 'Дуусгаад тохиргоо руу очно уу','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'WooCommerce конвенцуудтай нийцүүлэн төлбөр тооцооны утасны талбарын харагдах байдлын сонголтыг хуучин утгаас шинэчилнэ үү.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'WooCommerce конвенцуудтай нийцүүлэн тээвэрлэлтийн утасны талбарын харагдах байдлын сонголтыг хуучин утгаас шинэчилнэ үү.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'Захиалгын хураангуй дэвсгэр өнгөний тохиргоог шинэ Хуваах дизайны хоёрдогч баганын дэвсгэр өнгөний сонголт руу хуулна уу.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'Biteship залгаасыг ашиглах үед сайжруулсан сонголтын талбарын функц үргэлж идэвхгүй байдаг.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Германы зах зээлийг ашиглах үед захиалгын байршил нь үргэлж &quot;Захиалгын хураангуйгаас доош&quot; байхаар тохируулагдсан байдаг. Энэ нэмэлт өргөтгөл нь захиалгын хураангуйгаас доош захиалга өгөх товчлуур болон хууль ёсны тэмдэглэгээний нүдийг харуулахыг шаарддаг.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'WooCommerce-д зориулж Germanized ашиглах үед захиалгын байрлалыг үргэлж &quot;Захиалгын хураангуйгаас доош&quot; гэж тохируулдаг. Энэ залгаас нь захиалгын хураангуйгаас доош захиалга өгөх товчлуур болон хууль ёсны тэмдэглэгээний нүдийг харуулахыг шаарддаг.','Edit pickup locations' => 'Авах байршлыг засах','Use local pickup label from WooCommerce settings' => 'WooCommerce тохиргооноос орон нутгийн авах шошгыг ашиглана уу','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'Идэвхжүүлсэн үед төлбөр тооцооны хэсэгт байрлах авах сонголтын шошго нь WooCommerce авах байршлын тохиргооны гарчигтай тохирч байна. Идэвхгүй болгосон үед шошго нь Fluid Checkout-с орчуулж болох &quot;Орон нутгийн авах&quot; текстийг ашигладаг.','Migration class %s must implement get_migration_steps().' => '%s шилжүүлгийн класс нь get_migration_steps() функцийг хэрэгжүүлэх ёстой.','Migration class %s returned an empty get_migration_steps() list.' => '%s шилжүүлгийн класс нь хоосон get_migration_steps() жагсаалт буцаасан.','Checkout design customization' => 'Төлбөрийн загварын тохируулга','Make your checkout pages match your brand, without custom CSS.' => 'Захиалгат CSS ашиглахгүйгээр кассын хуудсаа өөрийн брэндтэй тохируулаарай.','Change the style of the header, footer, steps, sections, order summary, cart items and coupons.' => 'Толгой хэсэг, хөл хэсэг, алхам, хэсэг, захиалгын хураангуй, сагсны бараа болон купоны хэв маягийг өөрчлөх.','Change the style of buttons and form fields.' => 'Товчлуур болон маягтын талбаруудын хэв маягийг өөрчлөх.','Preview your changes on checkout, cart, thank you, and order pay pages before saving them.' => 'Өөрчлөлтүүдээ хадгалахаасаа өмнө төлбөр тооцоо, сагс, талархал, захиалгын төлбөрийн хуудсан дээр урьдчилан харна уу.','Set separate colors for light and dark mode.' => 'Гэрэл болон бараан горимд тусдаа өнгийг тохируулна уу.','Design' => 'Дизайн','Some changes to the database are required.' => 'Мэдээллийн санд зарим өөрчлөлт оруулах шаардлагатай байна.','New settings page 🎉' => 'Шинэ тохиргооны хуудас 🎉','Fluid Checkout has a redesigned settings experience with guided setup, live page previews, and easier navigation. Open settings to explore the new layout and discover new ways to configure your checkout.' => 'Fluid Checkout нь удирдамжтай тохиргоо, шууд хуудасны урьдчилсан тойм, хялбар навигаци бүхий шинэчилсэн тохиргооны туршлагатай. Шинэ байршлыг судлах, төлбөр тооцоогоо тохируулах шинэ аргуудыг нээхийн тулд тохиргоог нээнэ үү.','Go to settings' => 'Тохиргоо руу очих','Since Fluid Checkout 5.0, settings are saved differently. Your settings have been migrated but legacy options are still stored in the database.' => 'Fluid Checkout 5.0 хувилбараас хойш тохиргоог өөрөөр хадгалсан. Таны тохиргоог шилжүүлсэн боловч хуучин сонголтууд нь мэдээллийн санд хадгалагдсан хэвээр байна.','Your store has been running for at least 2 months on the new settings so these legacy options can now be cleaned from the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'Таны дэлгүүр шинэ тохиргоон дээр дор хаяж 2 сар ажиллаж байгаа тул эдгээр хуучин сонголтуудыг одоо мэдээллийн сангаас цэвэрлэх боломжтой. Цэвэрлэгээний дараа, хэрэв та залгаасын өмнөх хувилбарууд руу шинэчлэх шаардлагатай бол бүх тохиргоонд анхдагч утгыг ашиглах болно гэдгийг анхаарна уу.','Fluid Checkout legacy settings cleanup' => 'Fluid Checkout-н хуучин тохиргоог цэвэрлэх','Usage tracking is optional and off by default. It helps us improve compatibility and support. You can preview the exact data before it is sent, and turn it off at any time.' => 'Хэрэглээг хянах нь сонголттой бөгөөд анхдагчаар идэвхгүй байдаг. Энэ нь бидэнд нийцтэй байдал болон дэмжлэгийг сайжруулахад тусалдаг. Та яг нарийн өгөгдлийг илгээхээс өмнө урьдчилан харж, хүссэн үедээ унтрааж болно.','When you turn it on, Fluid Checkout receives your site domain and basic environment details: WordPress, PHP and WooCommerce versions, language, store country, currency and timezone, your active theme, and your installed plugins and their versions. You can also choose to include monthly order counts and sales totals. No customer or user data is ever sent.' => 'Та үүнийг асаахад Fluid Checkout нь таны сайтын домэйн болон үндсэн орчны мэдээллийг хүлээн авна: WordPress, PHP болон WooCommerce хувилбарууд, хэл, дэлгүүрийн улс, валют болон цагийн бүс, таны идэвхтэй загвар, суулгасан залгаасууд болон тэдгээрийн хувилбарууд. Та мөн сарын захиалгын тоо болон борлуулалтын нийт дүнг оруулахаар сонгож болно. Хэрэглэгч эсвэл хэрэглэгчийн мэдээллийг хэзээ ч илгээхгүй.','Keep it OFF' => 'Үүнийг УНТРААХ','Review usage tracking' => 'Хэрэглээний хяналтыг хянах','Turn on usage tracking' => 'Хэрэглээний хяналтыг асаана уу','Design customizations without code' => 'Кодгүйгээр дизайны тохиргоо хийх','Express checkout from supported payment methods' => 'Дэмжигдсэн төлбөрийн аргуудаас экспресс төлбөр тооцоо хийх','Choose a color for %s' => '%s-д зориулж өнгө сонгоно уу','Clear %s' => '%s-г цэвэрлэх','Clear' => 'Цэвэрлэгээ','Enter a valid CSS value.' => 'Хүчинтэй CSS утга оруулна уу.','Get faster support and help us improve compatibility and measure impact. Usage tracking is optional and off by default. <a href="%s">Review usage tracking</a> in the tools settings. You can preview the data and turn it off at any time.' => 'Илүү хурдан дэмжлэг авч, нийцтэй байдлыг сайжруулж, нөлөөллийг хэмжихэд бидэнд тусална уу. Хэрэглээг хянах нь сонголттой бөгөөд анхдагчаар идэвхгүй байдаг. Хэрэгслийн тохиргооноос <a href="%s">хэрэглээний хяналтыг хянана уу</a> . Та өгөгдлийг урьдчилан харж, хүссэн үедээ унтрааж болно.','Preview data' => 'Өгөгдлийг урьдчилан харах','General styles for the checkout steps, order summary and other sections. Applies to the checkout and add payment method pages. With PRO, also applies to the cart, order pay, thank you (order received) and view order pages.' => 'Төлбөр тооцооны алхамууд, захиалгын хураангуй болон бусад хэсгүүдийн ерөнхий хэв маяг. Төлбөр тооцоо хийх болон төлбөрийн арга нэмэх хуудсанд хамаарна. PRO-той бол сагс, захиалгын төлбөр, баярлалаа (захиалга хүлээн авсан) болон захиалгын хуудсуудыг үзэх зэрэгт мөн хамаарна.','Color scheme' => 'Өнгөний схем','Use the light or dark colors on the checkout pages, or use the dark colors only when the theme is in dark mode.' => 'Төлбөрийн хуудсан дээр цайвар эсвэл бараан өнгийг ашиглаарай, эсвэл загвар нь бараан горимд байх үед л бараан өнгийг ашиглаарай.','Theme' => 'Сэдэв','Light' => 'Гэрэл','Dark' => 'Харанхуй','Change the checkout layout to multi-step to see these options.' => 'Эдгээр сонголтыг харахын тулд төлбөр тооцооны байршлыг олон алхамтай болгож өөрчилнө үү.','Display the checkout progress bar' => 'Төлбөрийн явцын мөрийг харуулах','Customers can create an account from checkout while placing their order.' => 'Үйлчлүүлэгчид захиалга өгөхдөө кассаас данс үүсгэх боломжтой.','Help guests finish checkout faster and create an account after they buy. Account matching associates guest orders with existing accounts, and delayed account creation lets customers register from the thank you page.' => 'Зочдод төлбөр тооцоогоо хурдан дуусгаж, худалдан авалт хийсний дараа данс үүсгэхэд нь тусална. Данс тохируулах нь зочдын захиалгыг одоо байгаа данстай холбож, данс үүсгэхийг хойшлуулснаар үйлчлүүлэгчид талархлын хуудаснаас бүртгүүлэх боломжтой болно.','Configure customer account options' => 'Харилцагчийн дансны сонголтуудыг тохируулах','The change could not be saved. Please try again.' => 'Өөрчлөлтийг хадгалж чадсангүй. Дахин оролдоно уу.','Settings navigation' => 'Тохиргооны навигаци','This setting has moved to %s.' => 'Энэ тохиргоог %s руу шилжүүлсэн.','another page' => 'өөр хуудас','Dismiss the message of %s' => '%s-н мессежийг хаах','Dismissed.' => 'Хаагдсан.','Undo?' => 'Буцаах уу?','Optional, and off by default. It helps us improve compatibility and provide you with faster support. You can preview the exact data before it is sent, and turn it off at any time. No customer or user data is ever sent.' => 'Заавал биш бөгөөд анхдагчаар идэвхгүй. Энэ нь бидэнд нийцтэй байдлыг сайжруулж, танд илүү хурдан дэмжлэг үзүүлэхэд тусалдаг. Та яг нарийн өгөгдлийг илгээхээс өмнө урьдчилан харж, хүссэн үедээ унтрааж болно. Хэрэглэгч эсвэл хэрэглэгчийн өгөгдлийг хэзээ ч илгээхгүй.','Nothing is sent right away unless you choose to send it. After that, usage data is sent about once a week, or about every 4 weeks if nothing has changed.' => 'Та илгээхээр сонгоогүй л бол юу ч шууд илгээгдэхгүй. Үүний дараа хэрэглээний өгөгдлийг долоо хоногт нэг удаа, хэрэв юу ч өөрчлөгдөөгүй бол 4 долоо хоног тутамд илгээнэ.','Basic environment' => 'Үндсэн орчин','Included whenever usage tracking is on. WordPress, PHP and WooCommerce versions, language, store country, currency and timezone, your active theme, and your installed plugins and their versions, including whether each plugin is active. Also your site domain, whether this is a multisite, and when Fluid Checkout plugins were first activated. A paid Fluid Checkout plugin can include a hashed license key, not the key itself.' => 'Хэрэглээний хяналт асаалттай үед багтана. WordPress, PHP болон WooCommerce хувилбарууд, хэл, дэлгүүрийн улс, валют болон цагийн бүс, таны идэвхтэй сэдэв, суулгасан залгаасууд болон тэдгээрийн хувилбарууд, үүнд залгаас бүр идэвхтэй байгаа эсэх. Мөн таны сайтын домэйн, энэ нь олон сайттай эсэх, Fluid Checkout залгаасууд анх хэзээ идэвхжсэн. Төлбөртэй Fluid Checkout залгаас нь түлхүүрийг өөрөө биш, харин хэшлэгдсэн лицензийн түлхүүрийг агуулж болно.','The active Fluid Checkout settings you have selected.' => 'Таны сонгосон идэвхтэй шингэн шалгах тохиргоо.','These settings are not sent yet.' => 'Эдгээр тохиргоог хараахан илгээгээгүй байна.','Store totals' => 'Дэлгүүрийн нийт дүн','Monthly order counts and sales totals for processing and completed orders, for finished months only. The first send can include the 12 months before you installed Fluid Checkout and each finished month since then. No customer or order details are included.' => 'Зөвхөн дууссан саруудад зориулсан боловсруулсан болон дууссан захиалгын сарын захиалгын тоо болон борлуулалтын нийт дүн. Эхний илгээлтэд Fluid Checkout суулгахаас өмнөх 12 сар болон түүнээс хойш дууссан сар бүр багтаж болно. Үйлчлүүлэгч эсвэл захиалгын дэлгэрэнгүй мэдээлэл ороогүй болно.','Legacy settings' => 'Хуучин тохиргоо','Since Fluid Checkout 5.0, settings are stored in profiles. Legacy individual option rows may still exist in the database from older versions to allow downgrades to a pre-5.0 plugin version.' => 'Fluid Checkout 5.0 хувилбараас хойш тохиргоонууд профайлд хадгалагддаг. 5.0-с өмнөх залгаасын хувилбар руу шинэчлэхийг зөвшөөрөхийн тулд хуучин хувилбаруудын өгөгдлийн санд хуучин сонголтын мөрүүд байсаар байж магадгүй.','Legacy settings cleanup' => 'Хуучин тохиргооны цэвэрлэгээ','Remove leftover individual option rows after you no longer need to downgrade to a pre-5.0 plugin version.' => '5.0-аас өмнөх залгаасын хувилбар руу шинэчлэх шаардлагагүй болсны дараа үлдсэн сонголтын мөрүүдийг устгана уу.','Clean legacy settings' => 'Хуучин тохиргоог цэвэрлэх','Address book integration' => 'Хаяг номын интеграци','VAT number' => 'НӨАТ-ын дугаар','Define limit of VAT Numbers a customer can save to their account.' => 'Үйлчлүүлэгч дансандаа хадгалж болох НӨАТ-ын дугаарын хязгаарыг тодорхойл.','One per account' => 'Данс бүрт нэг','Usage data preview' => 'Хэрэглээний өгөгдлийн урьдчилсан тойм','This is the exact usage data that would be sent with your current choices.' => 'Энэ бол таны одоогийн сонголтуудтай хамт илгээгдэх яг хэрэглээний өгөгдөл юм.','Loading preview...' => 'Урьдчилсан хувилбарыг ачаалж байна...','Could not load the preview. Try again.' => 'Урьдчилсан үзлэгийг ачаалж чадсангүй. Дахин оролдоно уу.','Could not send the usage data. Try again.' => 'Хэрэглээний өгөгдлийг илгээж чадсангүй. Дахин оролдоно уу.','Usage data sent.' => 'Хэрэглээний өгөгдөл илгээгдсэн.','Turn on and send now' => 'Асаагаад одоо илгээнэ үү','Usage data is already being sent. Try again in a moment.' => 'Хэрэглээний өгөгдлийг аль хэдийн илгээж байна. Хэсэг хугацааны дараа дахин оролдоно уу.','Usage tracking is turned off.' => 'Хэрэглээний хяналтыг унтраасан байна.','There is no usage data to send.' => 'Илгээх хэрэглээний өгөгдөл байхгүй байна.','This site cannot send usage data. Local and development sites are excluded.' => 'Энэ сайт хэрэглээний өгөгдлийг илгээх боломжгүй. Орон нутгийн болон хөгжүүлэлтийн сайтуудыг оруулаагүй болно.','Usage data was sent recently. Try again later.' => 'Хэрэглээний өгөгдлийг саяхан илгээсэн. Дараа дахин оролдоно уу.','The usage data could not be sent. Try again later.' => 'Хэрэглээний өгөгдлийг илгээж чадсангүй. Дараа дахин оролдоно уу.','Usage tracking is not available.' => 'Хэрэглээг хянах боломжгүй байна.','There is no usage data for these choices.' => 'Эдгээр сонголтуудын хэрэглээний мэдээлэл байхгүй байна.','You are not allowed to manage usage tracking.' => 'Та хэрэглээний хяналтыг удирдах эрхгүй.','Get only this add-on' => 'Зөвхөн энэ нэмэлтийг аваарай','Usage tracking is turned off by the %s constant in wp-config.php.' => 'Хэрэглээний хяналтыг wp-config.php файл дахь %s тогтмолоор идэвхгүй болгосон.','Physical products' => 'Физик бүтээгдэхүүнүүд','Downloads & Digital products' => 'Татаж авах болон дижитал бүтээгдэхүүнүүд','Services' => 'Үйлчилгээнүүд','Bookings' => 'Захиалга','Subscriptions' => 'Захиалга','Memberships' => 'Гишүүнчлэл','Shipping to address' => 'Хаяг руу хүргэлт','Pickup in store or at a location' => 'Дэлгүүрээс эсвэл байршлаас авах боломжтой','Ship to pickup point' => 'Авах цэг рүү тээвэрлэх','Local delivery' => 'Орон нутгийн хүргэлт','DTC - Direct to consumer' => 'DTC - Хэрэглэгч рүү шууд','B2B - To businesses' => 'B2B - Бизнес эрхлэгчдэд','your country' => 'танай улс','Only in %s' => 'Зөвхөн %s-ээр','Multiple countries' => 'Олон улс орон','Fashion, apparel, and accessories' => 'Загвар, хувцас, дагалдах хэрэгсэл','Health and beauty' => 'Эрүүл мэнд ба гоо сайхан','Electronics and computers' => 'Электроник болон компьютер','Food and drink' => 'Хоол хүнс, уух зүйлс','Home, furniture, and garden' => 'Гэр, тавилга, цэцэрлэг','Education and learning' => 'Боловсрол ба суралцах','Sports and recreation' => 'Спорт болон амралт чөлөөт цаг','Arts and crafts' => 'Урлаг ба гар урлал','Other' => 'Бусад','Please select what type of products or services you sell.' => 'Та ямар төрлийн бүтээгдэхүүн эсвэл үйлчилгээ зарахаа сонгоно уу.','Please select who you sell to.' => 'Хэнд зарахаа сонгоно уу.','Please select where your customers are located.' => 'Үйлчлүүлэгчид хаана байрлаж байгааг сонгоно уу.','Please enter a valid email address for the newsletter.' => 'Мэдээллийн товхимолд хүчинтэй имэйл хаяг оруулна уу.','Please select at least one product type.' => 'Дор хаяж нэг бүтээгдэхүүний төрөл сонгоно уу.','Please select at least one delivery method for physical products.' => 'Бодит бүтээгдэхүүний хувьд дор хаяж нэг хүргэлтийн аргыг сонгоно уу.','About your store' => 'Танай дэлгүүрийн тухай','Products & delivery' => 'Бүтээгдэхүүн ба хүргэлт','Recommended setup' => 'Санал болгож буй тохиргоо','Show recommendations already applied' => 'Хэрэгжүүлсэн зөвлөмжийг харуулах','Hide recommendations already applied' => 'Өмнө нь хэрэгжүүлсэн зөвлөмжийг нуух','Show more recommendations' => 'Бусад зөвлөмжийг харуулах','Show fewer recommendations' => 'Цөөн зөвлөмж харуулах','Welcome to Fluid Checkout!' => 'Fluid Checkout-д тавтай морил!','It is great to have you here with us! We will be guiding you through the setup process – your answers to a few questions will help us recommend checkout settings for your store.' => 'Тантай энд хамт байгаад баяртай байна! Бид танд тохиргооны үйл явцад туслах болно - хэдэн асуултанд өгсөн хариулт тань танай дэлгүүрийн төлбөр тооцооны тохиргоог санал болгоход бидэнд туслах болно.','What type of products or services do you sell?' => 'Та ямар төрлийн бүтээгдэхүүн эсвэл үйлчилгээ зардаг вэ?','Who do you predominantly sell to?' => 'Та голчлон хэнд борлуулалт хийдэг вэ?','Where are your customers located?' => 'Танай үйлчлүүлэгчид хаана байрладаг вэ?','Help improve Fluid Checkout with optional usage tracking (no customer data).' => 'Нэмэлт хэрэглээний хяналт (хэрэглэгчийн мэдээлэл байхгүй) ашиглан Fluid Checkout-г сайжруулахад тусална уу.','You can review and change this anytime under Tools → Usage tracking.' => 'Та үүнийг Хэрэгслүүд → Хэрэглээний хяналт хэсэгт хүссэн үедээ хянаж, өөрчилж болно.','Email address' => 'И-мэйл хаяг','Newsletter opt-in' => 'Мэдээллийн товхимолд бүртгүүлэх','Opt-in to receive news about new features, tips and recommendations from the Fluid Checkout team directly in your inbox.' => 'Fluid Checkout багийн шинэ функц, зөвлөгөө, зөвлөмжийн талаарх мэдээг шууд имэйл хаягаараа хүлээн авахын тулд бүртгүүлнэ үү.','What do you sell, and how do you deliver physical products?' => 'Та юу зардаг вэ, мөн бодит бүтээгдэхүүнийг хэрхэн хүргэдэг вэ?','What do you sell?' => 'Та юу зардаг вэ?','How do you handle delivery of your products?' => 'Танайх бүтээгдэхүүн хүргэлтийг хэрхэн зохицуулдаг вэ?','Recommended checkout settings' => 'Санал болгож буй төлбөр тооцооны тохиргоо','No more recommendations to apply.' => 'Хэрэглэх зөвлөмж байхгүй.','Show already applied' => 'Өмнө нь хэрэглэсэнийг харуулах','Based on what you told us, these checkout options are a good starting point. You can turn recommended options off before applying them.' => 'Таны бидэнд хэлсэн зүйл дээр үндэслэн эдгээр төлбөрийн сонголтууд нь сайн эхлэлийн цэг юм. Та санал болгож буй сонголтуудыг хэрэгжүүлэхээсээ өмнө унтрааж болно.','You can change any of these settings later in the Fluid Checkout settings.' => 'Та эдгээр тохиргооны аль нэгийг дараа нь Fluid Checkout тохиргооноос өөрчилж болно.','Apply settings & finish setup' => 'Тохиргоог хэрэгжүүлж, тохиргоог дуусгах','Your recommended setup options have been applied.' => 'Таны санал болгосон тохиргооны сонголтуудыг хэрэгжүүлсэн.','Test your checkout process and return to Fluid Checkout settings to adjust any settings if needed.' => 'Шаардлагатай бол төлбөр тооцооны үйл явцаа шалгаад, Fluid Checkout тохиргоо руу буцаж очоод тохиргоогоо тохируулна уу.','You can use the built-in live preview in settings to see how settings changes affect your checkout before saving them.' => 'Тохиргооны өөрчлөлтүүд таны төлбөр тооцоонд хэрхэн нөлөөлөхийг харахын тулд та тэдгээрийг хадгалахаасаа өмнө тохиргоонд суурилуулсан шууд урьдчилсан тоймыг ашиглаж болно.','If you need help, <a href="%s" target="_blank" rel="noopener noreferrer">contact our support team</a>.' => 'Хэрэв танд тусламж хэрэгтэй бол <a href="%s" target="_blank" rel="noopener noreferrer">манай дэмжлэгийн багтай холбогдоно уу</a> .','Subscription account creation' => 'Захиалгын данс үүсгэх','Allow subscription customers to create an account during checkout' => 'Захиалгат хэрэглэгчдэд төлбөр тооцооны үеэр бүртгэл үүсгэхийг зөвшөөрөх','Enable account creation at checkout for subscription purchases when account creation for other orders is disabled.' => 'Бусад захиалгын данс үүсгэхийг идэвхгүй болгосон үед захиалгын худалдан авалтын төлбөр тооцооны үед данс үүсгэхийг идэвхжүүлнэ үү.','Multi-step checkout' => 'Олон шатлалт төлбөр тооцоо','Clear steps with few fields at a time to guide customers through checkout and keep them focused.' => 'Үйлчлүүлэгчдийг төлбөр тооцооны явцад чиглүүлж, анхаарлаа төвлөрүүлэхийн тулд нэг дор цөөн хэдэн талбар ашиглан тодорхой алхамуудыг хийгээрэй.','Single-step checkout' => 'Нэг алхамтай төлбөр тооцоо','Show all fields at once. Ideal for short checkouts such as digital products or services that don\'t require much information.' => 'Бүх талбарыг нэг дор харуулах. Их мэдээлэл шаарддаггүй дижитал бүтээгдэхүүн эсвэл үйлчилгээ гэх мэт богино хугацааны төлбөр тооцоонд тохиромжтой.','Keep theme header and footer' => 'Сэдвийн толгой болон доод хэсгийг хадгалах','Show the store header and footer at checkout instead of the distraction-free layout. Useful for B2B stores that need site navigation during checkout.' => 'Төлбөр тооцоо хийх үед анхаарал сарниулахгүй зохион байгуулалтын оронд дэлгүүрийн толгой болон доод хэсгийг харуулна. Төлбөр тооцоо хийх үед сайтын навигаци шаардлагатай B2B дэлгүүрүүдэд хэрэгтэй.','Edit cart at checkout' => 'Төлбөр тооцооны үеэр сагсыг засах','Let customers change quantities and remove items without leaving checkout.' => 'Үйлчлүүлэгчдэд кассаас гаралгүйгээр тоо хэмжээг нь өөрчилж, бараагаа авах боломжийг олгоно уу.','Billing before shipping' => 'Тээвэрлэлтийн өмнөх төлбөр тооцоо','Collect the billing address as a step before shipping so business buyers can enter invoice details first.' => 'Бизнес худалдан авагчид эхлээд нэхэмжлэхийн мэдээллийг оруулах боломжтой байхын тулд тээвэрлэлтийн өмнө төлбөрийн хаягийг нэг алхам болгон цуглуул.','Shipping methods before address' => 'Хаягнаас өмнө хүргэлтийн аргууд','Show shipping methods before the address so customers can see other delivery options such as local pickup.' => 'Үйлчлүүлэгчид орон нутгийн хүргэлт гэх мэт бусад хүргэлтийн сонголтуудыг харах боломжтой байхын тулд хаягийн өмнө хүргэлтийн аргыг харуулна уу.','Shipping methods after address' => 'Хаягийн дараа хүргэлтийн аргууд','Ask for the shipping address first, then show shipping methods that match that destination.' => 'Эхлээд тээвэрлэлтийн хаягийг асуугаад дараа нь тухайн очих газартай тохирох тээвэрлэлтийн аргыг харуулна уу.','Require billing company' => 'Төлбөр тооцооны компани шаардлагатай','Make the billing company field required so invoices include a company name for business orders.' => 'Бизнесийн захиалгын компанийн нэрийг нэхэмжлэхэд оруулахын тулд төлбөр тооцооны компанийн талбарыг заавал бөглөнө үү.','Hide additional order notes' => 'Нэмэлт захиалгын тэмдэглэлийг нуух','Hide the additional order notes field to keep checkout shorter. Customers rarely need it for most orders.' => 'Төлбөр тооцоог богино байлгахын тулд нэмэлт захиалгын тэмдэглэлийн талбарыг нууна уу. Үйлчлүүлэгчид ихэнх захиалгад үүнийг ховорхон ашигладаг.','Enable optimized cart page' => 'Оновчтой сагсны хуудсыг идэвхжүүлэх','Improved cart page to reduce cart abandonment rates and give customers a consistent experience.' => 'Сагс хаях түвшинг бууруулж, үйлчлүүлэгчдэд тогтвортой туршлагыг олгохын тулд сагсны хуудсыг сайжруулсан.','Enable optimized thank you page' => 'Оновчтой талархлын хуудсыг идэвхжүүлэх','Improved thank you page to give customers a consistent experience.' => 'Үйлчлүүлэгчдэд тогтвортой туршлага олгохын тулд талархлын хуудсыг сайжруулсан.','Enable optimized order pay page' => 'Оновчтой захиалгын төлбөрийн хуудсыг идэвхжүүлэх','Improved order pay page to give customers a consistent experience.' => 'Үйлчлүүлэгчдэд тогтвортой туршлагыг олгохын тулд захиалгын төлбөрийн хуудсыг сайжруулсан.','Suggest verified addresses as customers type to reduce typos and failed deliveries.' => 'Үг үсгийн алдаа болон хүргэлт амжилтгүй болохоос сэргийлэхийн тулд үйлчлүүлэгчид бичих үед баталгаажсан хаягуудыг санал болгоно уу.','Address book at checkout' => 'Төлбөр тооцооны үед хаягийн дэвтэр','Let logged-in customers pick a saved address instead of retyping it every time.' => 'Нэвтэрсэн хэрэглэгчдэд хадгалсан хаягаа дахин бичихийн оронд сонгох боломжийг олгоно уу.','Let customers place orders without creating an account first.' => 'Үйлчлүүлэгчдэд эхлээд бүртгэл үүсгэхгүйгээр захиалга өгөх боломжийг олгоорой.','Require account to checkout' => 'Төлбөр тооцоо хийхийн тулд данс шаардлагатай','Turn off guest checkout so customers must log in or create an account before placing an order.' => 'Захиалга өгөхөөсөө өмнө үйлчлүүлэгчид нэвтрэх эсвэл бүртгэл үүсгэх шаардлагатай тул зочны төлбөр тооцоог унтраана уу.','Login reminder at checkout' => 'Төлбөр тооцоо хийх үед нэвтрэх сануулга','Offer a login link at checkout so returning customers can reuse saved details faster.' => 'Дахин үйлчлүүлэгчид хадгалсан мэдээллээ илүү хурдан ашиглах боломжтой байхын тулд төлбөр тооцооны үеэр нэвтрэх холбоос санал болгоорой.','Account matching at checkout' => 'Төлбөр тооцоо хийх үед дансны тохируулга','Detect when the email already belongs to an account and prompt the customer to log in instead of creating a duplicate.' => 'Имэйл аль хэдийн бүртгэлд хамаарах эсэхийг илрүүлж, давхардсан имэйл үүсгэхийн оронд хэрэглэгчээс нэвтрэхийг хүс.','Local pickup or in-store collection' => 'Орон нутгаас авах эсвэл дэлгүүрээс авах','Let customers choose at checkout where to pick up their order.' => 'Үйлчлүүлэгчдэд захиалгаа хаанаас авахаа төлбөр тооцооны үеэр сонгох боломжийг олгоно уу.','Optional shipping phone' => 'Нэмэлт хүргэлтийн утас','Show a shipping phone field customers can fill when carriers or delivery partners need a contact number.' => 'Тээвэрлэгч эсвэл хүргэлтийн түншүүдэд холбоо барих дугаар хэрэгтэй үед үйлчлүүлэгчид бөглөж болох тээврийн утасны талбарыг харуулна уу.','Require shipping phone' => 'Тээвэрлэлтийн утас шаардлагатай','Require a phone number on the shipping address for delivery coordination and failed-delivery recovery.' => 'Хүргэлтийн зохицуулалт болон хүргэлт амжилтгүй болсон тохиолдолд сэргээхийн тулд хүргэлтийн хаяг дээр утасны дугаар шаардана уу.','International phone fields' => 'Олон улсын утасны талбарууд','Show country-aware phone inputs so customers can enter numbers in the correct international format.' => 'Үйлчлүүлэгчид дугааруудыг зөв олон улсын форматаар оруулах боломжтой байхын тулд улс оронтой холбоотой утасны оролтыг харуулна уу.','One per saved address' => 'Хадгалсан хаяг бүрт нэг','Button label for applying coupon codesApply' => 'Өргөдөл гаргах','Checkout step titleContact' => 'Холбоо барих','Checkout step titleShipping' => 'Хүргэлт','Checkout step titleBilling' => 'Тооцоо','Checkout step titlePayment' => 'Төлбөр','Checkout substep change link labelChange' => 'Өөрчлөх','Checkout substep save link labelSave changes' => 'Өөрчлөлтүүдийг хадгалах','Substep review textNone.' => 'Байхгүй.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'Зураг сонгогдсонгүй.','Settings sectionCart' => 'Сагс','Settings sectionOrder pay' => 'Захиалгын төлбөр','Settings sectionThank you' => 'Баярлалаа','Settings section titleIntegrations' => 'Интеграци','Settings section titleLicense keys' => 'Лицензийн түлхүүрүүд','Captcha positionBefore place order section' => 'Захиалга өгөхийн өмнө хэсэг','Captcha positionBefore place order button' => 'Захиалга өгөхийн өмнө товчлуур','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'Хаах','Log in link label at checkout contact stepLog in' => 'Нэвтрэх','Log in separator label at for when guest checkout is disabledOr continue below' => 'Эсвэл доор үргэлжлүүлнэ үү','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'Эсвэл зочноор үргэлжлүүлээрэй','Clear image selection on admin pages.Remove image' => 'Зургийг арилгах','shipping packagesShipping %d' => 'Хүргэлт %d','shipping packagesShipping' => 'Тээвэрлэлт','Used as fallback for "Proceed to next step" button labelnext step' => 'дараагийн алхам','Substep review checkbox valueYes' => 'Тийм','Substep review checkbox line%1$s: %2$s' => '%1$s: %2$s','Dummy customer first name in the admin previewJohn' => 'Жон','Dummy customer last name in the admin previewDoe' => 'Доу','Dummy customer company in the admin previewExample Company' => 'Жишээ компани','Dummy customer street address in the admin preview123 Main Street' => '123 Төв гудамж','Dummy customer city in the admin previewAnytown' => 'Аль ч хотхон','Dummy order notes in the admin previewPlease leave the package at the front door.' => 'Багцыг үүдний хаалган дээр үлдээнэ үү.','Dummy product name in the admin previewBeanie' => 'Beanie','Dummy product name in the admin previewCap' => 'Малгай','Dummy product name in the admin previewT-Shirt' => 'Футболк','Dummy order update in the admin previewWe received your order and will send you an update when it ships.' => 'Бид таны захиалгыг хүлээн авсан бөгөөд хүргэлт гарах үед танд шинэчлэлт илгээх болно.','Dummy download in the admin previewUser guide' => 'Хэрэглэгчийн гарын авлага','Google Places API versionsPlaces API (New)' => 'Газруудын API (Шинэ)','Google Places API versionsPlaces API (Legacy)' => 'Газруудын API (Уламжлалт)','Brasil API versionsVersion 1' => '1-р хувилбар','Brasil API versionsVersion 2' => '2-р хувилбар','Delayed account creation benefits placeholder text✔ Checkout faster next time
